  border:0;padding:18px 76px 16px;cursor:pointer;color:#fff5e6;overflow:hidden;
  background:linear-gradient(180deg,#a81418,#6b090c);
  clip-path:polygon(12px 0,calc(100% - 12px) 0,100% 50%,calc(100% - 12px) 100%,12px 100%,0 50%);
  box-shadow:0 18px 40px rgba(0,0,0,.55),inset 0 1px 0 rgba(255,190,160,.25);
  transition:transform .15s,filter .15s;
  font-family:var(--font-ui);
}
.start-btn:hover{transform:translateY(-2px) scale(1.015);filter:brightness(1.14)}
.start-btn:active{transform:translateY(0) scale(.99)}
.start-glow{position:absolute;inset:0;background:linear-gradient(110deg,transparent 20%,rgba(255,210,170,.24) 48%,transparent 70%);transform:translateX(-120%);animation:sheen 3.6s ease-in-out infinite}
@keyframes sheen{0%,55%{transform:translateX(-120%)}80%,100%{transform:translateX(120%)}}
.start-text{font-family:var(--font-display);font-weight:700;font-size:20px;letter-spacing:.14em;position:relative}
.start-sub{font-size:10px;letter-spacing:.34em;color:#e5b9a5;position:relative}
.start-btn.small{padding:14px 50px 12px}
.start-btn.small .start-text{font-size:16px}
.controls-strip{
  display:flex;justify-content:center;flex-wrap:wrap;gap:10px 22px;margin:24px auto 0;
  color:#938876;font-size:11px;letter-spacing:.14em;
}
.controls-strip>div{display:flex;align-items:center;gap:5px}
.controls-strip kbd{
  font-family:var(--font-ui);font-weight:600;font-size:11px;color:#d7c8ad;
  border:1px solid rgba(201,161,95,.3);border-bottom-width:2px;border-radius:3px;
  padding:2px 6px;min-width:22px;text-align:center;background:rgba(30,20,16,.7);
}
.controls-strip span{color:#8e8270;margin-left:4px}
.touch-note{display:none;margin:18px 0 0;color:#a99982;font-size:12px;letter-spacing:.1em}
.fine-print{margin:16px auto 0;color:#5f574c;font-size:10.5px;letter-spacing:.08em;max-width:600px}
.ghost-btn{
  background:none;border:1px solid rgba(201,161,95,.28);color:#b9a98f;padding:10px 24px;
  font-family:var(--font-ui);font-size:12px;letter-spacing:.2em;cursor:pointer;transition:.2s;
}
.ghost-btn:hover{border-color:var(--gold);color:var(--gold-bright)}

/* ---------- HUD ---------- */
#hud{position:absolute;inset:0;z-index:10;pointer-events:none;font-family:var(--font-ui)}
.hud-top{position:absolute;top:max(16px,env(safe-area-inset-top));left:max(18px,env(safe-area-inset-left));right:max(18px,env(safe-area-inset-right));display:flex;justify-content:space-between;align-items:flex-start;gap:18px}
.hud-block{display:flex;flex-direction:column;line-height:1;min-width:110px;text-shadow:0 2px 10px #000}
.hud-eyebrow{font-size:11px;letter-spacing:.34em;color:var(--gold);margin-bottom:2px}
.hud-big{font-family:var(--font-display);font-weight:900;font-size:46px;color:#f0e3ca;line-height:.9}
.hud-sub{font-size:11px;letter-spacing:.18em;color:#a69881;margin-top:4px}
.hud-sub b{color:#e6d5b8;font-weight:600}
.score-block{text-align:right;align-items:flex-end}
.hud-center{flex:1;display:flex;justify-content:center;padding-top:8px}
.crowd-meter{width:min(300px,32vw);text-align:center}
.crowd-label{font-size:9.5px;letter-spacing:.32em;color:#9e8f78;display:block;margin-bottom:5px}
.crowd-track{height:4px;background:rgba(0,0,0,.55);border:1px solid rgba(201,161,95,.18);position:relative;overflow:hidden}
.crowd-track i{display:block;height:100%;width:8%;background:linear-gradient(90deg,#6f4a1f,var(--gold-bright));box-shadow:0 0 12px rgba(240,210,154,.5);transition:width .3s ease}
.hud-bottom{position:absolute;left:max(18px,env(safe-area-inset-left));right:max(18px,env(safe-area-inset-right));bottom:max(18px,env(safe-area-inset-bottom));display:flex;justify-content:space-between;align-items:flex-end;gap:20px}
.vitals{width:min(320px,36vw)}
.vital-row{display:flex;align-items:center;gap:10px;margin-top:7px}
.vital-label{width:54px;font-size:9.5px;letter-spacing:.2em;color:#9a8c76;flex:0 0 auto}
.vital-track{position:relative;height:15px;flex:1;background:rgba(4,3,3,.72);border:1px solid rgba(201,161,95,.22);overflow:hidden}
.vital-track i{display:block;height:100%;width:100%;transition:width .16s ease;position:relative}
.vital-track.health i{background:linear-gradient(90deg,#52080a,#b31419 70%,#d63c32);box-shadow:0 0 14px rgba(180,20,25,.35)}
.vital-track.health i:after{content:'';position:absolute;inset:0;background:repeating-linear-gradient(115deg,transparent 0 8px,rgba(0,0,0,.2) 8px 10px)}
.vital-track.stamina{height:7px}
.vital-track.stamina i{width:100%;background:linear-gradient(90deg,#53432b,#c9a15f)}
.vital-track span{position:absolute;right:6px;top:50%;transform:translateY(-50%);font-size:10px;letter-spacing:.1em;color:#f0dbca;text-shadow:0 1px 3px #000;font-weight:600}
.weapon-panel{
  display:flex;align-items:center;gap:10px;padding:8px 14px 8px 8px;position:relative;
