/* crosshair */
.crosshair{position:absolute;left:50%;top:50%;width:38px;height:38px;transform:translate(-50%,-50%);opacity:.9;transition:opacity .15s,transform .1s}
.crosshair .ch-dot{position:absolute;left:50%;top:50%;width:3px;height:3px;margin:-1.5px;background:rgba(245,230,210,.9);border-radius:50%;box-shadow:0 0 4px #000}
.crosshair .ch-line{position:absolute;background:rgba(240,225,205,.75);box-shadow:0 0 3px rgba(0,0,0,.8)}
.ch-1,.ch-2{width:1px;height:9px;left:50%;margin-left:-.5px}
.ch-1{top:0}.ch-2{bottom:0}
.ch-3,.ch-4{height:1px;width:9px;top:50%;margin-top:-.5px}
.ch-3{left:0}.ch-4{right:0}
.crosshair.hammer{width:46px;height:46px}
.crosshair.hammer .ch-line{background:rgba(230,190,140,.8)}
#target-tag{
  position:absolute;left:50%;top:calc(50% + 32px);transform:translateX(-50%);
  font-size:10px;letter-spacing:.24em;color:#e9d8bd;text-shadow:0 2px 5px #000;
  opacity:0;transition:opacity .15s;white-space:nowrap;
}
#target-tag.show{opacity:.92}
#target-tag .tt-bar{display:block;width:70px;height:2px;background:rgba(0,0,0,.6);margin:4px auto 0;border:1px solid rgba(201,161,95,.25)}
#target-tag .tt-bar i{display:block;height:100%;background:#b31419;transition:width .1s}
.hitmarker{position:absolute;left:50%;top:50%;width:30px;height:30px;transform:translate(-50%,-50%);opacity:0}
.hitmarker.active{animation:hit .17s ease-out}
.hitmarker i{position:absolute;width:8px;height:1.5px;background:#f5e8d2;box-shadow:0 0 4px #000}
.hitmarker i:nth-child(1){left:0;top:6px;transform:rotate(45deg)}
.hitmarker i:nth-child(2){right:0;top:6px;transform:rotate(-45deg)}
.hitmarker i:nth-child(3){left:0;bottom:6px;transform:rotate(-45deg)}
.hitmarker i:nth-child(4){right:0;bottom:6px;transform:rotate(45deg)}
@keyframes hit{0%{opacity:1;transform:translate(-50%,-50%) scale(.7)}100%{opacity:0;transform:translate(-50%,-50%) scale(1.35)}}
#damage-dirs{position:absolute;inset:0;overflow:hidden}
.dmg-dir{position:absolute;left:50%;top:50%;width:180px;height:180px;margin:-90px;border-radius:50%;border-top:4px solid rgba(200,20,24,.8);filter:blur(1px);animation:dmgFade .9s ease-out forwards}
@keyframes dmgFade{0%{opacity:1;transform:rotate(var(--r)) scale(.9)}100%{opacity:0;transform:rotate(var(--r)) scale(1.15)}}

