import * as THREE from '../vendor/three.module.js'

export const clamp = (v, a, b) => Math.max(a, Math.min(b, v))
export const lerp = (a, b, t) => a + (b - a) * t
export const damp = (a, b, lambda, dt) => lerp(a, b, 1 - Math.exp(-lambda * dt))
export const rand = (a = 0, b = 1) => a + Math.random() * (b - a)
export const randInt = (a, b) => Math.floor(rand(a, b + 1))
export const choice = (arr) => arr[Math.floor(Math.random() * arr.length)]
export const TAU = Math.PI * 2

export function roman(num) {
  const map = [[1000,'M'],[900,'CM'],[500,'D'],[400,'CD'],[100,'C'],[90,'XC'],[50,'L'],[40,'XL'],[10,'X'],[9,'IX'],[5,'V'],[4,'IV'],[1,'I']]
  let out = ''
  for (const [n, s] of map) while (num >= n) { out += s; num -= n }
  return out
}

export function makeCanvasTexture(w, h, draw, { repeat = null, srgb = true, anisotropy = 8 } = {}) {
  const c = document.createElement('canvas')
  c.width = w; c.height = h
  const ctx = c.getContext('2d')
  draw(ctx, w, h)
  const tex = new THREE.CanvasTexture(c)
  if (srgb) tex.colorSpace = THREE.SRGBColorSpace
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping
  tex.anisotropy = anisotropy
  if (repeat) tex.repeat.set(repeat[0], repeat[1])
  return tex
}

function noise(ctx, w, h, count, alpha, size = 2, colors = ['#000', '#fff']) {
  for (let i = 0; i < count; i++) {
    ctx.globalAlpha = rand(alpha * 0.25, alpha)
    ctx.fillStyle = choice(colors)
    const s = rand(0.5, size)
    ctx.fillRect(rand(0, w), rand(0, h), s, s)
  }
  ctx.globalAlpha = 1
}

export function makeSandTexture() {
  return makeCanvasTexture(1024, 1024, (ctx, w, h) => {
    const g = ctx.createLinearGradient(0, 0, 0, h)
    g.addColorStop(0, '#a68a5f'); g.addColorStop(0.45, '#947a55'); g.addColorStop(1, '#7e6648')
    ctx.fillStyle = g; ctx.fillRect(0, 0, w, h)

    // broad damp patches and old stains
    for (let i = 0; i < 90; i++) {
      const x = rand(0, w), y = rand(0, h), r = rand(30, 190)
      const rg = ctx.createRadialGradient(x, y, 0, x, y, r)
      const dark = Math.random() < 0.6
      rg.addColorStop(0, dark ? 'rgba(70,50,33,.12)' : 'rgba(210,190,150,.10)')
      rg.addColorStop(1, 'rgba(0,0,0,0)')
      ctx.fillStyle = rg; ctx.beginPath(); ctx.arc(x, y, r, 0, TAU); ctx.fill()
    }
    // raked arcs
    ctx.globalAlpha = 0.09; ctx.strokeStyle = '#3b2c1c'; ctx.lineWidth = 2
    for (let i = 0; i < 26; i++) {
      const y = rand(0, h)
      ctx.beginPath()
      for (let x = 0; x <= w; x += 16) ctx.lineTo(x, y + Math.sin(x * 0.014 + i) * 8)
      ctx.stroke()
    }
    ctx.globalAlpha = 1
    // pebbles / grain
    noise(ctx, w, h, 26000, 0.24, 2.4, ['#5f4a30', '#c4a97a', '#3c2d1d', '#d8c193'])
    // tiny dark flecks
    noise(ctx, w, h, 6000, 0.45, 1.4, ['#38291a', '#2a1d12'])
    // footfall scars
    ctx.strokeStyle = 'rgba(59,42,25,.18)'; ctx.lineWidth = 5
    for (let i = 0; i < 40; i++) {
      ctx.beginPath(); ctx.arc(rand(0, w), rand(0, h), rand(8, 26), 0, TAU); ctx.stroke()
    }
  }, { repeat: [7, 9] })
}

export function makeStoneTexture() {
  return makeCanvasTexture(1024, 512, (ctx, w, h) => {
    ctx.fillStyle = '#241c18'; ctx.fillRect(0, 0, w, h)
    const rows = 7, rowH = h / rows
    for (let r = 0; r < rows; r++) {
      const y = r * rowH
      let x = (r % 2) ? -rand(40, 90) : -rand(0, 40)
      while (x < w) {
        const bw = rand(95, 175), gap = rand(4, 8)
        const c = Math.floor(rand(33, 52))
        const grad = ctx.createLinearGradient(0, y, 0, y + rowH)
        grad.addColorStop(0, `hsl(22 ${rand(5, 13)}% ${c + 8}%)`)
        grad.addColorStop(0.5, `hsl(24 ${rand(4, 10)}% ${c}%)`)
        grad.addColorStop(1, `hsl(20 ${rand(6, 14)}% ${c - 9}%)`)
        ctx.fillStyle = grad
        ctx.beginPath()
        const pad = 3
        ctx.roundRect(x + gap / 2, y + pad, bw - gap, rowH - pad * 2, 3)
        ctx.fill()
        // brick face texture
        ctx.save(); ctx.clip()
        noise(ctx, w, h, 220, 0.09, 2.2, ['#000', '#fff', '#6a4a34'])
        ctx.restore()
        // edge highlight
        ctx.strokeStyle = 'rgba(0,0,0,.35)'; ctx.lineWidth = 2
        ctx.stroke()
        x += bw
      }
    }
    // mortar noise + cracks
    noise(ctx, w, h, 12000, 0.2, 1.8, ['#0c0908', '#5e4a3a'])
    ctx.strokeStyle = 'rgba(8,5,4,.35)'; ctx.lineWidth = 1.5
    for (let i = 0; i < 28; i++) {
      let x = rand(0, w), y = rand(0, h)
      ctx.beginPath(); ctx.moveTo(x, y)
      for (let s = 0; s < rand(3, 7); s++) { x += rand(-24, 24); y += rand(8, 26); ctx.lineTo(x, y) }
      ctx.stroke()
    }
    // moss
    for (let i = 0; i < 40; i++) {
      const x = rand(0, w), y = rand(0, h)
      const rg = ctx.createRadialGradient(x, y, 0, x, y, rand(8, 30))
      rg.addColorStop(0, 'rgba(63,74,38,.18)'); rg.addColorStop(1, 'rgba(0,0,0,0)')
      ctx.fillStyle = rg; ctx.beginPath(); ctx.arc(x, y, 30, 0, TAU); ctx.fill()
    }
  }, { repeat: [3, 1] })
}

export function makeWoodTexture() {
  return makeCanvasTexture(512, 512, (ctx, w, h) => {
    ctx.fillStyle = '#3a2418'; ctx.fillRect(0, 0, w, h)
    const planks = 7, pw = w / planks
    for (let i = 0; i < planks; i++) {
      const x = i * pw
      const g = ctx.createLinearGradient(x, 0, x + pw, 0)
      const l = rand(16, 27)
      g.addColorStop(0, `hsl(24 42% ${l - 4}%)`)
      g.addColorStop(0.4, `hsl(26 38% ${l + 5}%)`)
      g.addColorStop(1, `hsl(22 44% ${l - 2}%)`)
      ctx.fillStyle = g; ctx.fillRect(x + 1, 0, pw - 2, h)
      ctx.strokeStyle = 'rgba(12,7,5,.4)'; ctx.lineWidth = 2
      for (let k = 0; k < 5; k++) {
        let yy = rand(0, h), xx = x + rand(4, pw - 4)
        ctx.beginPath(); ctx.moveTo(xx, yy)
        for (let s = 0; s < 8; s++) { xx += rand(-2, 2); yy += rand(8, 20); ctx.lineTo(xx, yy) }
        ctx.stroke()
      }
      // nail heads
      ctx.fillStyle = 'rgba(15,12,10,.8)'
      for (let k = 0; k < 2; k++) { ctx.beginPath(); ctx.arc(x + pw / 2 + rand(-6, 6), rand(0, h), 2, 0, TAU); ctx.fill() }
    }
    noise(ctx, w, h, 4000, 0.12, 2, ['#000', '#b08050'])
  }, { repeat: [2, 2] })
}

export function makeSkyTexture() {
  return makeCanvasTexture(2048, 1024, (ctx, w, h) => {
    const g = ctx.createLinearGradient(0, 0, 0, h)
    g.addColorStop(0.0, '#07070f')
    g.addColorStop(0.2, '#14101d')
    g.addColorStop(0.38, '#3e1620')
    g.addColorStop(0.5, '#8f3423')
    g.addColorStop(0.56, '#d9803c')
    g.addColorStop(0.60, '#6b2a1c')
    g.addColorStop(0.72, '#24100d')
    g.addColorStop(1.0, '#0a0605')
    ctx.fillStyle = g; ctx.fillRect(0, 0, w, h)

    // sun glow
    const sx = w * 0.34, sy = h * 0.515
    const sun = ctx.createRadialGradient(sx, sy, 0, sx, sy, 300)
    sun.addColorStop(0, 'rgba(255,238,200,1)')
    sun.addColorStop(0.07, 'rgba(255,205,130,.92)')
    sun.addColorStop(0.24, 'rgba(230,120,55,.32)')
    sun.addColorStop(0.6, 'rgba(120,40,20,.10)')
    sun.addColorStop(1, 'rgba(0,0,0,0)')
    ctx.fillStyle = sun; ctx.beginPath(); ctx.arc(sx, sy, 300, 0, TAU); ctx.fill()

    // clouds
    for (let i = 0; i < 42; i++) {
      const x = rand(0, w), y = rand(h * 0.18, h * 0.56), rw = rand(90, 380), rh = rand(10, 44)
      const cg = ctx.createRadialGradient(x, y, 0, x, y, rw)
      cg.addColorStop(0, `rgba(${randInt(30, 80)},${randInt(14, 34)},${randInt(22, 42)},${rand(0.12, 0.34)})`)
      cg.addColorStop(1, 'rgba(0,0,0,0)')
      ctx.save(); ctx.translate(x, y); ctx.scale(1, rh / rw); ctx.translate(-x, -y)
      ctx.fillStyle = cg; ctx.beginPath(); ctx.arc(x, y, rw, 0, TAU); ctx.fill(); ctx.restore()
    }
    // stars
    for (let i = 0; i < 260; i++) {
      ctx.globalAlpha = rand(0.1, 0.8); ctx.fillStyle = '#dfe4ff'
      const s = rand(0.5, 1.6)
      ctx.fillRect(rand(0, w), rand(0, h * 0.33), s, s)
    }
    ctx.globalAlpha = 1
    // distant haze mountains silhouette
    ctx.fillStyle = 'rgba(12,8,8,.6)'
    ctx.beginPath(); ctx.moveTo(0, h * 0.585)
    for (let x = 0; x <= w; x += 32) ctx.lineTo(x, h * 0.585 - Math.abs(Math.sin(x * 0.004) * 28 + Math.sin(x * 0.011) * 12))
    ctx.lineTo(w, h * 0.7); ctx.lineTo(0, h * 0.7); ctx.closePath(); ctx.fill()
  }, { repeat: [1, 1] })
}

export function makeBloodTexture() {
  return makeCanvasTexture(512, 512, (ctx, w, h) => {
    ctx.clearRect(0, 0, w, h)
    const cx = w * 0.5, cy = h * 0.5
    const blob = (x, y, rx, ry, rot, color) => {
      ctx.save(); ctx.translate(x, y); ctx.rotate(rot)
      ctx.fillStyle = color; ctx.beginPath(); ctx.ellipse(0, 0, rx, ry, 0, 0, TAU); ctx.fill(); ctx.restore()
    }
    // central irregular pool
    ctx.fillStyle = 'rgba(83,5,8,.96)'
    ctx.beginPath()
    const points = 14
    for (let i = 0; i <= points; i++) {
      const a = (i / points) * TAU
      const r = 92 + Math.sin(a * 3 + 1.2) * 26 + Math.sin(a * 7) * 14
      const x = cx + Math.cos(a) * r, y = cy + Math.sin(a) * r * 0.86
      if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y)
    }
    ctx.closePath(); ctx.fill()
    // inner darker center
    blob(cx, cy, 55, 45, 0.3, 'rgba(48,2,4,.85)')
    // satellite splats
    for (let i = 0; i < 26; i++) {
      const a = rand(0, TAU), d = rand(95, 225)
      const rx = rand(4, 26) * (1 - d / 340), ry = rx * rand(0.6, 1.3)
      blob(cx + Math.cos(a) * d, cy + Math.sin(a) * d * 0.9, rx, ry, rand(0, TAU), `rgba(${randInt(70, 110)},${randInt(3, 10)},${randInt(5, 12)},${rand(0.5, 0.95)})`)
    }
    // drips / streaks
    for (let i = 0; i < 16; i++) {
      const a = rand(0, TAU), d = rand(40, 120)
      const x = cx + Math.cos(a) * d, y = cy + Math.sin(a) * d
      ctx.strokeStyle = `rgba(${randInt(60, 100)},3,6,${rand(0.35, 0.8)})`
      ctx.lineWidth = rand(2, 8); ctx.lineCap = 'round'
      ctx.beginPath(); ctx.moveTo(x, y)
      ctx.quadraticCurveTo(x + rand(-16, 16), y + rand(10, 24), x + rand(-20, 20), y + rand(28, 70))
      ctx.stroke()
    }
    // tiny droplets
    for (let i = 0; i < 90; i++) {
      const a = rand(0, TAU), d = rand(130, 250)
      blob(cx + Math.cos(a) * d, cy + Math.sin(a) * d, rand(1, 5), rand(1, 4), rand(0, TAU), `rgba(${randInt(65, 100)},2,5,${rand(0.3, 0.8)})`)
    }
  }, { repeat: [1, 1] })
}

export function makeFlameTexture() {
  return makeCanvasTexture(128, 256, (ctx, w, h) => {
    ctx.clearRect(0, 0, w, h)
    const g = ctx.createRadialGradient(w / 2, h * 0.66, 2, w / 2, h * 0.62, w * 0.6)
    g.addColorStop(0, 'rgba(255,250,210,1)')
    g.addColorStop(0.22, 'rgba(255,190,70,.95)')
    g.addColorStop(0.52, 'rgba(230,80,20,.55)')
    g.addColorStop(1, 'rgba(120,20,5,0)')
    ctx.fillStyle = g
    ctx.beginPath(); ctx.moveTo(w / 2, 4)
    ctx.bezierCurveTo(w * 0.96, h * 0.4, w * 0.82, h * 0.96, w / 2, h * 0.98)
    ctx.bezierCurveTo(w * 0.14, h * 0.94, w * 0.05, h * 0.42, w / 2, 4)
    ctx.fill()
    // inner core
    const g2 = ctx.createRadialGradient(w / 2, h * 0.76, 1, w / 2, h * 0.76, w * 0.3)
    g2.addColorStop(0, 'rgba(255,255,230,1)')
    g2.addColorStop(0.6, 'rgba(255,220,120,.7)')
    g2.addColorStop(1, 'rgba(255,120,30,0)')
    ctx.fillStyle = g2; ctx.beginPath(); ctx.ellipse(w / 2, h * 0.78, w * 0.22, h * 0.2, 0, 0, TAU); ctx.fill()
  }, { repeat: [1, 1] })
}

export function makeEmblemTexture() {
  return makeCanvasTexture(512, 512, (ctx, w, h) => {
    ctx.clearRect(0, 0, w, h)
    const cx = w / 2, cy = h * 0.46
    ctx.fillStyle = '#160b0a'
    // skull silhouette
    ctx.beginPath()
    ctx.ellipse(cx, cy, 118, 132, 0, 0, TAU); ctx.fill()
    ctx.beginPath(); ctx.roundRect(cx - 82, cy + 74, 164, 94, 26); ctx.fill()
    ctx.beginPath(); ctx.ellipse(cx, cy + 78, 118, 34, 0, 0, TAU); ctx.fill()
    // cheekbones
    ctx.beginPath(); ctx.arc(cx - 92, cy + 26, 34, 0, TAU); ctx.fill()
    ctx.beginPath(); ctx.arc(cx + 92, cy + 26, 34, 0, TAU); ctx.fill()
    // eyes (holes)
    ctx.fillStyle = '#8e0d10'
    ctx.beginPath(); ctx.ellipse(cx - 48, cy + 4, 34, 42, 0.18, 0, TAU); ctx.fill()
    ctx.beginPath(); ctx.ellipse(cx + 48, cy + 4, 34, 42, -0.18, 0, TAU); ctx.fill()
    ctx.fillStyle = '#0b0505'
    ctx.beginPath(); ctx.ellipse(cx - 48, cy + 6, 25, 32, 0.18, 0, TAU); ctx.fill()
    ctx.beginPath(); ctx.ellipse(cx + 48, cy + 6, 25, 32, -0.18, 0, TAU); ctx.fill()
    // nose
    ctx.beginPath(); ctx.moveTo(cx, cy + 38); ctx.lineTo(cx - 16, cy + 76); ctx.lineTo(cx + 16, cy + 76); ctx.closePath(); ctx.fill()
    // teeth
    ctx.fillStyle = '#160b0a'
    for (let i = -4; i <= 4; i++) ctx.fillRect(cx + i * 20 - 7, cy + 118, 13, 38)
    // cross swords behind
    ctx.save(); ctx.translate(cx, cy + 30); ctx.rotate(-0.68)
    ctx.fillStyle = 'rgba(160,128,76,.55)'; ctx.fillRect(-5, -210, 10, 420); ctx.restore()
    ctx.save(); ctx.translate(cx, cy + 30); ctx.rotate(0.68)
    ctx.fillStyle = 'rgba(160,128,76,.55)'; ctx.fillRect(-5, -210, 10, 420); ctx.restore()
    // border ring
    ctx.strokeStyle = 'rgba(190,155,95,.5)'; ctx.lineWidth = 5
    ctx.beginPath(); ctx.arc(cx, cy + 26, 225, 0, TAU); ctx.stroke()
  }, { repeat: [1, 1] })
}

export function makeDustTexture() {
  return makeCanvasTexture(64, 64, (ctx, w, h) => {
    const g = ctx.createRadialGradient(w / 2, h / 2, 0, w / 2, h / 2, w / 2)
    g.addColorStop(0, 'rgba(255,235,200,.9)')
    g.addColorStop(0.4, 'rgba(230,200,150,.35)')
    g.addColorStop(1, 'rgba(200,170,120,0)')
    ctx.fillStyle = g; ctx.fillRect(0, 0, w, h)
  }, { srgb: true })
}

export function makeClothTexture() {
  return makeCanvasTexture(512, 512, (ctx, w, h) => {
    ctx.fillStyle = '#4d0b0d'; ctx.fillRect(0, 0, w, h)
    const g = ctx.createLinearGradient(0, 0, 0, h)
    g.addColorStop(0, 'rgba(0,0,0,.4)'); g.addColorStop(.5, 'rgba(0,0,0,0)'); g.addColorStop(1, 'rgba(0,0,0,.35)')
    ctx.fillStyle = g; ctx.fillRect(0, 0, w, h)
    for (let i = 0; i < 5000; i++) {
      ctx.globalAlpha = rand(0.02, 0.1); ctx.fillStyle = Math.random() < 0.5 ? '#000' : '#c08060'
      ctx.fillRect(rand(0, w), rand(0, h), rand(1, 3), rand(1, 6))
    }
    ctx.globalAlpha = 1
  }, { repeat: [1, 1] })
}

export function roundedRectShape(w, h, r) {
  const s = new THREE.Shape()
  const x = -w / 2, y = -h / 2
  s.moveTo(x + r, y)
  s.lineTo(x + w - r, y); s.quadraticCurveTo(x + w, y, x + w, y + r)
  s.lineTo(x + w, y + h - r); s.quadraticCurveTo(x + w, y + h, x + w - r, y + h)
  s.lineTo(x + r, y + h); s.quadraticCurveTo(x, y + h, x, y + h - r)
  s.lineTo(x, y + r); s.quadraticCurveTo(x, y, x + r, y)
  return s
}

export function roundedBox(w, h, d, r = 0.05, bevel = 0.5) {
  const shape = roundedRectShape(w, h, Math.min(r, Math.min(w, h) * 0.45))
  const geo = new THREE.ExtrudeGeometry(shape, {
    depth: Math.max(0.001, d - r * bevel), bevelEnabled: true, bevelSegments: 2,
    steps: 1, bevelSize: r * bevel * 0.6, bevelThickness: r * bevel * 0.6, curveSegments: 4
  })
  geo.center()
  geo.computeVertexNormals()
  return geo
}

export function mesh(geo, mat, x = 0, y = 0, z = 0) {
  const m = new THREE.Mesh(geo, mat)
  m.position.set(x, y, z)
  m.castShadow = true
  m.receiveShadow = true
  return m
}

export function disposeObject(obj) {
  obj.traverse?.(o => {
    if (o.geometry) o.geometry.dispose?.()
    if (o.material) {
      const mats = Array.isArray(o.material) ? o.material : [o.material]
      for (const m of mats) m.dispose?.()
    }
  })
}

export function bloodColor() {
  return new THREE.Color().setHSL(rand(0.985, 1.01) % 1, rand(0.72, 0.95), rand(0.12, 0.24))
}

import { rand, clamp, choice } from './utils.js'

export class AudioEngine {
  constructor() {
    this.ctx = null
    this.ready = false
    this.muted = false
    this.crowdLevel = 0.15
    this.crowdTarget = 0.15
    this.cheerCooldown = 0
    this.time = 0
    this.waveDrone = 0
  }

  init() {
    if (this.ready) return
    const AC = window.AudioContext || window.webkitAudioContext
    if (!AC) return
    try {
      this.ctx = new AC()
    } catch { return }
    const ctx = this.ctx
    this.master = ctx.createGain()
    this.master.gain.value = 0.72
    this.comp = ctx.createDynamicsCompressor()
    this.comp.threshold.value = -16
    this.comp.knee.value = 22
    this.comp.ratio.value = 4
    this.comp.attack.value = 0.004
    this.comp.release.value = 0.24
    this.master.connect(this.comp)
    this.comp.connect(ctx.destination)

    // arena reverb
    this.reverb = ctx.createConvolver()
    this.reverb.buffer = this._impulse(2.4, 2.6)
    this.wet = ctx.createGain()
    this.wet.gain.value = 0.28
    this.reverb.connect(this.wet)
    this.wet.connect(this.master)

    this.noise = this._noiseBuffer(2.5)
    this.ready = true
    this._startAmbience()
  }

  resume() {
    if (!this.ready) this.init()
    if (this.ctx?.state === 'suspended') this.ctx.resume()
  }

  _noiseBuffer(seconds) {
    const ctx = this.ctx
    const len = Math.floor(ctx.sampleRate * seconds)
    const buf = ctx.createBuffer(1, len, ctx.sampleRate)
    const data = buf.getChannelData(0)
    for (let i = 0; i < len; i++) data[i] = Math.random() * 2 - 1
    return buf
  }

  _impulse(seconds, decay) {
    const ctx = this.ctx
    const len = Math.floor(ctx.sampleRate * seconds)
    const buf = ctx.createBuffer(2, len, ctx.sampleRate)
    for (let c = 0; c < 2; c++) {
      const d = buf.getChannelData(c)
      for (let i = 0; i < len; i++) {
        const t = i / len
        d[i] = (Math.random() * 2 - 1) * Math.pow(1 - t, decay) * (1 - t * 0.2)
      }
    }
    return buf
  }

  _panner(pan = 0) {
    if (!this.ctx.createStereoPanner) return null
    const p = this.ctx.createStereoPanner()
    p.pan.value = clamp(pan, -1, 1)
    return p
  }

  _out(node, pan = 0, wet = 0.3) {
    const p = this._panner(pan)
    if (p) { node.connect(p); p.connect(this.master) } else node.connect(this.master)
    if (wet > 0) {
      const w = this.ctx.createGain(); w.gain.value = wet
      node.connect(w); w.connect(this.reverb)
    }
  }

  _env(gain, t0, attack, hold, release, peak) {
    const g = gain.gain
    g.cancelScheduledValues(t0)
    g.setValueAtTime(0.0001, t0)
    g.exponentialRampToValueAtTime(Math.max(0.0002, peak), t0 + attack)
    g.setValueAtTime(Math.max(0.0002, peak), t0 + attack + hold)
    g.exponentialRampToValueAtTime(0.0001, t0 + attack + hold + release)
  }

  _noiseBurst(dur, gain, type, freq, q, pan = 0, wet = 0.3, sweepTo = null) {
    if (!this.ready) return
    const ctx = this.ctx, t = ctx.currentTime
    const src = ctx.createBufferSource()
    src.buffer = this.noise
    src.loop = true
    const f = ctx.createBiquadFilter()
    f.type = type; f.frequency.setValueAtTime(freq, t); f.Q.value = q
    if (sweepTo) f.frequency.exponentialRampToValueAtTime(Math.max(40, sweepTo), t + dur)
    const g = ctx.createGain()
    this._env(g, t, Math.min(0.02, dur * 0.2), dur * 0.35, dur * 0.65, gain)
    src.connect(f); f.connect(g)
    this._out(g, pan, wet)
    src.start(t); src.stop(t + dur + 0.08)
  }

  _tone(freq, dur, gain, type = 'sine', pan = 0, wet = 0.25, glideTo = null, attack = 0.005) {
    if (!this.ready) return
    const ctx = this.ctx, t = ctx.currentTime
    const o = ctx.createOscillator()
    o.type = type
    o.frequency.setValueAtTime(freq, t)
    if (glideTo) o.frequency.exponentialRampToValueAtTime(Math.max(20, glideTo), t + dur)
    const g = ctx.createGain()
    this._env(g, t, attack, dur * 0.25, dur * 0.7, gain)
    o.connect(g)
    this._out(g, pan, wet)
    o.start(t); o.stop(t + dur + 0.1)
  }

  ui() {
    if (!this.ready) return
    this._tone(520, 0.06, 0.05, 'triangle', 0, 0.15)
  }

  whoosh(pan = 0, heavy = false) {
    if (!this.ready) return
    this._noiseBurst(heavy ? 0.34 : 0.22, heavy ? 0.34 : 0.24, 'bandpass', heavy ? 420 : 900, heavy ? 0.9 : 1.4, pan, 0.25, heavy ? 130 : 280)
    if (heavy) this._tone(70, 0.22, 0.16, 'sine', pan, 0.2, 42)
  }

  hurt(pan = 0) {
    if (!this.ready) return
    this._tone(96, 0.34, 0.26, 'sine', pan, 0.3, 44)
    this._noiseBurst(0.18, 0.16, 'lowpass', 900, 0.8, pan, 0.25)
    this._tone(3100, 1.6, 0.018, 'sine', 0, 0.4)
  }

  flesh(power = 1, pan = 0, bone = false) {
    if (!this.ready) return
    const p = clamp(power, 0.4, 1.6)
    this._noiseBurst(0.14, 0.3 * p, 'lowpass', 700, 0.9, pan, 0.35, 160)
    this._tone(78, 0.2, 0.22 * p, 'sine', pan, 0.3, 42)
    this._noiseBurst(0.09, 0.16 * p, 'bandpass', 1600, 1.6, pan, 0.3, 500)
    if (bone) this.crunch(pan, 0.7 * p)
    setTimeout(() => this.splat(pan, 0.5 * p), 40)
  }

  crunch(pan = 0, power = 1) {
    if (!this.ready) return
    const ctx = this.ctx, t = ctx.currentTime
    for (let i = 0; i < 4; i++) {
      const src = ctx.createBufferSource(); src.buffer = this.noise; src.loop = true
      const f = ctx.createBiquadFilter(); f.type = 'bandpass'
      f.frequency.value = rand(900, 2600); f.Q.value = rand(3, 8)
      const g = ctx.createGain()
      const start = t + i * rand(0.008, 0.03)
      g.gain.setValueAtTime(0, start)
      g.gain.linearRampToValueAtTime(rand(0.08, 0.2) * power, start + 0.004)
      g.gain.exponentialRampToValueAtTime(0.0001, start + rand(0.035, 0.09))
      src.connect(f); f.connect(g); this._out(g, pan, 0.25)
      src.start(start); src.stop(start + 0.12)
    }
    this._tone(rand(55, 90), 0.28, 0.2 * power, 'sine', pan, 0.3, 38)
  }

  splat(pan = 0, power = 1) {
    if (!this.ready) return
    this._noiseBurst(0.18, 0.16 * power, 'bandpass', rand(450, 850), 0.7, pan, 0.35, 180)
  }

  sever(pan = 0, bone = false) {
    if (!this.ready) return
    this._noiseBurst(0.28, 0.3, 'lowpass', 1200, 0.8, pan, 0.4, 120)
    this._tone(140, 0.3, 0.2, 'sawtooth', pan, 0.35, 42)
    this.splat(pan, 1.2)
    if (bone) setTimeout(() => this.crunch(pan, 1), 60)
    setTimeout(() => this.gurgle(pan), 120)
  }

  gurgle(pan = 0) {
    if (!this.ready) return
    this._tone(rand(120, 180), 0.5, 0.055, 'sawtooth', pan, 0.4, rand(60, 90))
    this._noiseBurst(0.35, 0.06, 'bandpass', rand(300, 500), 2.5, pan, 0.5)
  }

  clang(pan = 0) {
    if (!this.ready) return
    this._tone(1180, 0.28, 0.06, 'square', pan, 0.45, 940)
    this._tone(1760, 0.22, 0.04, 'triangle', pan, 0.45, 1400)
  }

  horn() {
    if (!this.ready) return
    const ctx = this.ctx, t = ctx.currentTime
    for (const f of [55, 82.5, 110]) {
      const o = ctx.createOscillator(); o.type = 'sawtooth'; o.frequency.value = f
      const lp = ctx.createBiquadFilter(); lp.type = 'lowpass'; lp.frequency.value = 420; lp.Q.value = 2
      const g = ctx.createGain()
      g.gain.setValueAtTime(0.0001, t)
      g.gain.exponentialRampToValueAtTime(0.09, t + 0.35)
      g.gain.setValueAtTime(0.09, t + 1.1)
      g.gain.exponentialRampToValueAtTime(0.0001, t + 2.2)
      o.connect(lp); lp.connect(g); this._out(g, 0, 0.55)
      o.start(t); o.stop(t + 2.3)
    }
  }

  cheer(intensity = 0.6) {
    if (!this.ready) return
    if (this.cheerCooldown > 0) return
    this.cheerCooldown = 0.35
    const ctx = this.ctx, t = ctx.currentTime
    const amt = clamp(intensity, 0.15, 1)
    // roar
    const src = ctx.createBufferSource(); src.buffer = this.noise; src.loop = true
    const bp = ctx.createBiquadFilter(); bp.type = 'bandpass'; bp.frequency.value = 700; bp.Q.value = 0.55
    const g = ctx.createGain()
    g.gain.setValueAtTime(0.0001, t)
    g.gain.exponentialRampToValueAtTime(0.16 * amt, t + 0.18)
    g.gain.setValueAtTime(0.16 * amt, t + rand(0.5, 0.9))
    g.gain.exponentialRampToValueAtTime(0.0001, t + rand(1.1, 1.9))
    src.connect(bp); bp.connect(g); this._out(g, 0, 0.6)
    src.start(t); src.stop(t + 2.1)
    // voices
    const voices = Math.floor(6 + amt * 12)
    for (let i = 0; i < voices; i++) {
      const start = t + rand(0, 0.42)
      const dur = rand(0.35, 0.9)
      const o = ctx.createOscillator()
      o.type = 'sawtooth'
      const base = rand(120, 290) + (Math.random() < 0.3 ? 80 : 0)
      o.frequency.setValueAtTime(base, start)
      o.frequency.linearRampToValueAtTime(base * rand(0.82, 1.3), start + dur)
      const f1 = ctx.createBiquadFilter(); f1.type = 'bandpass'; f1.frequency.value = rand(500, 950); f1.Q.value = rand(4, 9)
      const f2 = ctx.createBiquadFilter(); f2.type = 'bandpass'; f2.frequency.value = rand(1100, 2100); f2.Q.value = rand(5, 11)
      const vg = ctx.createGain()
      vg.gain.setValueAtTime(0.0001, start)
      vg.gain.exponentialRampToValueAtTime(rand(0.008, 0.03) * amt, start + 0.08)
      vg.gain.exponentialRampToValueAtTime(0.0001, start + dur)
      o.connect(f1); o.connect(f2); f1.connect(vg); f2.connect(vg)
      this._out(vg, rand(-0.8, 0.8), 0.5)
      o.start(start); o.stop(start + dur + 0.05)
    }
  }

  boo() {
    if (!this.ready) return
    this._noiseBurst(1.6, 0.09, 'bandpass', 340, 1.2, 0, 0.6, 220)
    this._tone(90, 1.4, 0.04, 'sawtooth', 0, 0.5, 65)
  }

  waveStart() {
    this.horn()
    setTimeout(() => this.cheer(0.8), 350)
  }

  _startAmbience() {
    const ctx = this.ctx, t = ctx.currentTime
    // crowd murmur
    const src = ctx.createBufferSource(); src.buffer = this.noise; src.loop = true
    const lp = ctx.createBiquadFilter(); lp.type = 'lowpass'; lp.frequency.value = 520; lp.Q.value = 0.4
    const bp = ctx.createBiquadFilter(); bp.type = 'bandpass'; bp.frequency.value = 430; bp.Q.value = 0.5
    const g = ctx.createGain(); g.gain.value = this.crowdLevel * 0.1
    src.connect(lp); lp.connect(bp); bp.connect(g); this._out(g, 0, 0.2)
    src.start(t)
    this.crowdGain = g
    // low drone
    const dg = ctx.createGain(); dg.gain.value = 0.018
    const dlp = ctx.createBiquadFilter(); dlp.type = 'lowpass'; dlp.frequency.value = 180
    const o1 = ctx.createOscillator(); o1.type = 'sawtooth'; o1.frequency.value = 41.2
    const o2 = ctx.createOscillator(); o2.type = 'sawtooth'; o2.frequency.value = 61.7
    o1.connect(dlp); o2.connect(dlp); dlp.connect(dg); this._out(dg, 0, 0.3)
    o1.start(t); o2.start(t)
    this.droneGain = dg
    // torch crackle bed
    const cs = ctx.createBufferSource(); cs.buffer = this.noise; cs.loop = true
    const hp = ctx.createBiquadFilter(); hp.type = 'highpass'; hp.frequency.value = 2400
    const cg = ctx.createGain(); cg.gain.value = 0.008
    cs.connect(hp); hp.connect(cg); this._out(cg, 0, 0.15); cs.start(t)
  }

  setCrowd(intensity) {
    this.crowdTarget = clamp(intensity, 0.12, 1)
  }

  setMuted(m) {
    this.muted = m
    if (this.master) this.master.gain.setTargetAtTime(m ? 0 : 0.72, this.ctx.currentTime, 0.08)
  }

  update(dt) {
    if (!this.ready) return
    this.time += dt
    this.cheerCooldown = Math.max(0, this.cheerCooldown - dt)
    this.crowdLevel += (this.crowdTarget - this.crowdLevel) * Math.min(1, dt * 1.4)
    if (this.crowdGain) this.crowdGain.gain.setTargetAtTime(this.crowdLevel * 0.1, this.ctx.currentTime, 0.2)
    if (this.droneGain) this.droneGain.gain.setTargetAtTime(0.012 + this.crowdLevel * 0.02, this.ctx.currentTime, 0.3)
  }
}

import * as THREE from '../vendor/three.module.js'
import {
  makeSandTexture, makeStoneTexture, makeWoodTexture, makeSkyTexture, makeFlameTexture,
  makeEmblemTexture, makeDustTexture, makeClothTexture, roundedBox, mesh,
  rand, randInt, choice, clamp, lerp, TAU
} from './utils.js'

export const ARENA = {
  halfX: 13, halfZ: 17, wallH: 3.5,
  playerMinX: -12.35, playerMaxX: 12.35,
  playerMinZ: -16.1, playerMaxZ: 16.25,
  gates: [-6.6, 0, 6.6],
  gateZ: -16.55
}

export class World {
  constructor(scene, renderer) {
    this.scene = scene
    this.renderer = renderer
    this.torches = []
    this.banners = []
    this.time = 0
    this.quality = 1
    this._build()
  }

  _build() {
    const s = this.scene
    s.fog = new THREE.FogExp2(0x2a1411, 0.0145)
    s.background = new THREE.Color(0x0c0808)

    const aniso = Math.min(8, this.renderer.capabilities.getMaxAnisotropy())
    this.tex = {
      sand: makeSandTexture(),
      stone: makeStoneTexture(),
      wood: makeWoodTexture(),
      sky: makeSkyTexture(),
      flame: makeFlameTexture(),
      emblem: makeEmblemTexture(),
      cloth: makeClothTexture(),
      dust: makeDustTexture()
    }
    for (const t of Object.values(this.tex)) t.anisotropy = aniso

    this._lights()
    this._sky()
    this._ground()
    this._walls()
    this._stands()
    this._crowd()
    this._torches()
    this._banners()
    this._details()
    this._dust()
  }

  _lights() {
    const s = this.scene
    const hemi = new THREE.HemisphereLight(0x5d6f92, 0x24130d, 0.52)
    s.add(hemi)
    const amb = new THREE.AmbientLight(0x3a2018, 0.28)
    s.add(amb)

    const sun = new THREE.DirectionalLight(0xffb477, 3.4)
    sun.position.set(-26, 23, -14)
    sun.castShadow = true
    sun.shadow.mapSize.set(2048, 2048)
    sun.shadow.camera.left = -26
    sun.shadow.camera.right = 26
    sun.shadow.camera.top = 26
    sun.shadow.camera.bottom = -26
    sun.shadow.camera.near = 2
    sun.shadow.camera.far = 80
    sun.shadow.bias = -0.00035
    sun.shadow.normalBias = 0.035
    s.add(sun)
    s.add(sun.target)
    sun.target.position.set(0, 0, 0)

    // warm reflected fill from the sand
    const fill = new THREE.PointLight(0xff6a30, 24, 34, 2)
    fill.position.set(0, 7, 4)
    s.add(fill)
  }

  _sky() {
    const geo = new THREE.SphereGeometry(150, 40, 24)
    const mat = new THREE.MeshBasicMaterial({ map: this.tex.sky, side: THREE.BackSide, fog: false, depthWrite: false })
    const dome = new THREE.Mesh(geo, mat)
    dome.rotation.y = 2.4
    this.scene.add(dome)
    // sun disc glow sprite
    const glowTex = makeDustTexture()
    const sp = new THREE.Sprite(new THREE.SpriteMaterial({ map: glowTex, color: 0xffd9a0, transparent: true, opacity: 0.85, blending: THREE.AdditiveBlending, depthWrite: false, fog: false }))
    sp.position.set(-48, 26, -100)
    sp.scale.set(46, 46, 1)
    this.scene.add(sp)
  }

  _ground() {
    const sand = new THREE.MeshStandardMaterial({ map: this.tex.sand, roughness: 0.97, metalness: 0, color: 0xbfa886 })
    const ground = new THREE.Mesh(new THREE.PlaneGeometry(ARENA.halfX * 2, ARENA.halfZ * 2), sand)
    ground.rotation.x = -Math.PI / 2
    ground.receiveShadow = true
    this.scene.add(ground)

    // dark blood-soaked ring at the edge
    const edgeTex = makeSandTexture()
    edgeTex.repeat.set(2, 2)
    const edge = new THREE.Mesh(new THREE.RingGeometry(0, 1, 48), new THREE.MeshBasicMaterial({ color: 0x1a0d08, transparent: true, opacity: 0.0 }))
    edge.visible = false
    this.scene.add(edge)

    // outside/understructure
    const dark = new THREE.MeshStandardMaterial({ color: 0x120b08, roughness: 1 })
    const outer = new THREE.Mesh(new THREE.PlaneGeometry(90, 90), dark)
    outer.rotation.x = -Math.PI / 2
    outer.position.y = -0.06
    outer.receiveShadow = true
    this.scene.add(outer)
  }

  _wallBlock(w, h, d, x, y, z, mapRepeat = null) {
    const mat = new THREE.MeshStandardMaterial({
      map: this.tex.stone, roughness: 0.95, metalness: 0.02, color: 0xa08d78
    })
    if (mapRepeat) {
      // shared texture; clone so repeats can differ
      const m = mat.clone()
      m.map = this.tex.stone.clone()
      m.map.needsUpdate = true
      m.map.repeat.set(mapRepeat[0], mapRepeat[1])
      mat.dispose()
      const b = mesh(new THREE.BoxGeometry(w, h, d), m, x, y, z)
      this.scene.add(b)
      return b
    }
    const b = mesh(new THREE.BoxGeometry(w, h, d), mat, x, y, z)
    this.scene.add(b)
    return b
  }

  _walls() {
    const { halfX, halfZ, wallH } = ARENA
    const t = 0.7
    const wallMat = new THREE.MeshStandardMaterial({ map: this.tex.stone, roughness: 0.94, metalness: 0.02, color: 0x9b8874 })
    const capMat = new THREE.MeshStandardMaterial({ color: 0x2a201a, roughness: 0.95 })
    const trimMat = new THREE.MeshStandardMaterial({ color: 0x3b2b21, roughness: 0.9, metalness: 0.08 })

    const addWall = (w, h, d, x, y, z) => {
      const b = mesh(new THREE.BoxGeometry(w, h, d), wallMat, x, y, z)
      this.scene.add(b)
      return b
    }

    // side walls
    addWall(t, wallH, halfZ * 2 + t, -halfX - t / 2, wallH / 2, 0)
    addWall(t, wallH, halfZ * 2 + t, halfX + t / 2, wallH / 2, 0)
    // front wall
    addWall(halfX * 2 + t * 2, wallH, t, 0, wallH / 2, halfZ + t / 2)

    // back wall with three gate openings
    const gates = ARENA.gates
    const segs = []
    let cursor = -halfX - t / 2
    for (const gx of gates) {
      segs.push([cursor, gx - 1.75])
      cursor = gx + 1.75
    }
    segs.push([cursor, halfX + t / 2])
    for (const [a, b] of segs) {
      if (b - a < 0.1) continue
      addWall(b - a, wallH, t, (a + b) / 2, wallH / 2, -halfZ - t / 2)
    }
    // wall above gates
    for (const gx of gates) {
      addWall(3.5, wallH - 2.75, t, gx, 2.75 + (wallH - 2.75) / 2, -halfZ - t / 2)
    }

    // caps
    const cap = (w, d, x, z) => {
      const c = mesh(new THREE.BoxGeometry(w, 0.26, d), capMat, x, wallH + 0.13, z)
      this.scene.add(c)
    }
    cap(t + 0.3, halfZ * 2 + t, -halfX - t / 2, 0)
    cap(t + 0.3, halfZ * 2 + t, halfX + t / 2, 0)
    cap(halfX * 2 + t * 2, t + 0.3, 0, halfZ + t / 2)
    cap(halfX * 2 + t * 2, t + 0.3, 0, -halfZ - t / 2)

    // base skirt
    const skirt = new THREE.MeshStandardMaterial({ color: 0x241813, roughness: 1 })
    const skirtM = (w, d, x, z) => {
      const m = mesh(new THREE.BoxGeometry(w, 0.4, d), skirt, x, 0.2, z)
      this.scene.add(m)
    }
    skirtM(0.45, halfZ * 2, -halfX + 0.18, 0)
    skirtM(0.45, halfZ * 2, halfX - 0.18, 0)
    skirtM(halfX * 2, 0.45, 0, halfZ - 0.18)

    // pillars with torches
    const pillarGeo = new THREE.BoxGeometry(0.62, wallH + 0.9, 0.62)
    const pillarMats = []
    for (let i = 0; i < 8; i++) {
      const m = wallMat.clone()
      m.map = this.tex.stone.clone(); m.map.needsUpdate = true; m.map.repeat.set(1, 2)
      pillarMats.push(m)
    }
    let pi = 0
    const pillar = (x, z) => {
      const p = mesh(pillarGeo, pillarMats[pi++ % pillarMats.length], x, (wallH + 0.9) / 2, z)
      this.scene.add(p)
      const capG = mesh(new THREE.BoxGeometry(0.82, 0.18, 0.82), trimMat, x, wallH + 0.95, z)
      this.scene.add(capG)
    }
    for (const z of [-9, 0, 9]) { pillar(-halfX + 0.34, z); pillar(halfX - 0.34, z) }
    pillar(-halfX + 0.34, halfZ - 0.34); pillar(halfX - 0.34, halfZ - 0.34)

    // gate frames, portcullis and tunnel
    for (const gx of gates) {
      const frameMat = trimMat
      const f1 = mesh(new THREE.BoxGeometry(0.4, 3.0, 0.9), frameMat, gx - 1.95, 1.5, -halfZ)
      const f2 = mesh(new THREE.BoxGeometry(0.4, 3.0, 0.9), frameMat, gx + 1.95, 1.5, -halfZ)
      const top = mesh(new THREE.BoxGeometry(4.3, 0.55, 0.9), frameMat, gx, 3.05, -halfZ)
      this.scene.add(f1, f2, top)
      // dark tunnel
      const tunnel = new THREE.Mesh(new THREE.BoxGeometry(3.1, 2.7, 6), new THREE.MeshStandardMaterial({ color: 0x070504, roughness: 1 }))
      tunnel.position.set(gx, 1.35, -halfZ - 3.2)
      this.scene.add(tunnel)
      const inner = new THREE.Mesh(new THREE.PlaneGeometry(2.9, 2.5), new THREE.MeshBasicMaterial({ color: 0x050303 }))
      inner.position.set(gx, 1.3, -halfZ + 0.03)
      this.scene.add(inner)
      // portcullis bars
      const barMat = new THREE.MeshStandardMaterial({ color: 0x24211f, metalness: 0.75, roughness: 0.45 })
      for (let i = 0; i < 7; i++) {
        const bar = mesh(new THREE.BoxGeometry(0.075, 2.55, 0.075), barMat, gx - 1.35 + i * 0.45, 1.3, -halfZ - 0.18)
        this.scene.add(bar)
      }
      for (let j = 0; j < 2; j++) {
        const bar = mesh(new THREE.BoxGeometry(2.75, 0.07, 0.07), barMat, gx, 0.7 + j * 0.95, -halfZ - 0.18)
        this.scene.add(bar)
      }
      // torch inside gate
      this._addTorch(gx - 1.9, 2.6, -halfZ + 0.55, 0, 0, true)
    }

    // inner wall face shading / decorative panels
    const panelMat = new THREE.MeshStandardMaterial({ map: this.tex.stone, color: 0x6f5d4c, roughness: 1 })
    this.scene.add(new THREE.Mesh(new THREE.PlaneGeometry(halfX * 2, wallH * 0.7), panelMat))
    // noop position not needed
  }

  _stands() {
    const { halfX, halfZ, wallH } = ARENA
    const standMat = new THREE.MeshStandardMaterial({ map: this.tex.stone, color: 0x7e6b57, roughness: 1 })
    const underMat = new THREE.MeshStandardMaterial({ color: 0x140d0a, roughness: 1 })
    const tierH = 0.62, tierD = 1.05

    // dark outer mass
    const outerL = mesh(new THREE.BoxGeometry(4.2, wallH + 2.4, halfZ * 2 + 9), underMat, -halfX - 3.6, (wallH + 2.4) / 2, 0)
    const outerR = mesh(new THREE.BoxGeometry(4.2, wallH + 2.4, halfZ * 2 + 9), underMat, halfX + 3.6, (wallH + 2.4) / 2, 0)
    this.scene.add(outerL, outerR)

    const side = (sign) => {
      for (let i = 0; i < 3; i++) {
        const x = sign * (halfX + 0.58 + i * tierD)
        const top = wallH + 0.34 + i * tierH
        const step = mesh(new THREE.BoxGeometry(tierD, tierH, halfZ * 2 + 7), standMat, x, top - tierH / 2, 0)
        this.scene.add(step)
      }
    }
    side(-1); side(1)

    for (let i = 0; i < 3; i++) {
      const zBack = -halfZ - 0.58 - i * tierD
      const top = wallH + 0.34 + i * tierH
      this.scene.add(mesh(new THREE.BoxGeometry(halfX * 2 + 6, tierH, tierD), standMat, 0, top - tierH / 2, zBack))
      const zFront = halfZ + 0.58 + i * tierD
      this.scene.add(mesh(new THREE.BoxGeometry(halfX * 2 + 6, tierH, tierD), standMat, 0, top - tierH / 2, zFront))
    }

    // wooden rail in front of the first tier
    const railMat = new THREE.MeshStandardMaterial({ map: this.tex.wood, color: 0x8a6b4a, roughness: 0.9 })
    const rail = (w, d, x, z) => {
      const r = mesh(new THREE.BoxGeometry(w, 0.12, d), railMat, x, wallH + 0.9, z)
      this.scene.add(r)
      for (let k = -3; k <= 3; k++) {
        const post = mesh(new THREE.BoxGeometry(0.1, 1.0, 0.1), railMat, x + (w > d ? k * (w / 7) : 0), wallH + 0.45, z + (w > d ? 0 : k * (d / 7)))
        this.scene.add(post)
      }
    }
    rail(0.1, halfZ * 2 + 6, -halfX - 0.54, 0)
    rail(0.1, halfZ * 2 + 6, halfX + 0.54, 0)
  }

  _crowd() {
    const { halfX, halfZ, wallH } = ARENA
    const members = []
    const palette = [0x4d1f1a, 0x5c3320, 0x2d211a, 0x3b2a23, 0x6b2c22, 0x1f1a19, 0x533b28, 0x2b2f33, 0x6b5130, 0x3e1b1d]
    const skins = [0xc59a78, 0xa77a58, 0x8a5e40, 0x6e452e, 0xd1a887, 0x9b6c4f]
    const tierH = 0.62
    const add = (x, z, y, yaw) => members.push({ x, z, y, yaw, phase: rand(0, TAU), speed: rand(0.8, 1.6), palette: choice(palette), skin: choice(skins), height: rand(0.88, 1.1), girth: rand(0.85, 1.25) })

    // sides
    for (const sign of [-1, 1]) {
      for (let tier = 0; tier < 3; tier++) {
        const x = sign * (halfX + 0.62 + tier * 1.05)
        const y = wallH + 0.34 + tier * tierH
        for (let k = 0; k < 19; k++) {
          const z = -halfZ + 0.8 + k * ((halfZ * 2 - 1.6) / 18) + rand(-0.3, 0.3)
          add(x + rand(-0.12, 0.12), z, y, sign > 0 ? -Math.PI / 2 : Math.PI / 2)
        }
      }
    }
    // back + front
    for (const sign of [-1, 1]) {
      for (let tier = 0; tier < 3; tier++) {
        const z = sign * (halfZ + 0.62 + tier * 1.05) + sign * 0.15
        const y = wallH + 0.34 + tier * tierH
        for (let k = 0; k < 16; k++) {
          const x = -halfX + 0.7 + k * ((halfX * 2 - 1.4) / 15) + rand(-0.35, 0.35)
          add(x, z + rand(-0.12, 0.12), y, sign > 0 ? Math.PI : 0)
        }
      }
    }

    this.crowd = members
    const n = members.length
    const bodyGeo = new THREE.CylinderGeometry(0.155, 0.23, 0.58, 6)
    const headGeo = new THREE.SphereGeometry(0.13, 8, 6)
    const armGeo = new THREE.CapsuleGeometry(0.042, 0.28, 2, 5)
    const bodyMat = new THREE.MeshLambertMaterial({ color: 0xffffff })
    const headMat = new THREE.MeshLambertMaterial({ color: 0xffffff })
    const armMat = new THREE.MeshLambertMaterial({ color: 0xffffff })

    this.crowdBody = new THREE.InstancedMesh(bodyGeo, bodyMat, n)
    this.crowdHead = new THREE.InstancedMesh(headGeo, headMat, n)
    this.crowdArmL = new THREE.InstancedMesh(armGeo, armMat, n)
    this.crowdArmR = new THREE.InstancedMesh(armGeo, armMat, n)
    for (const im of [this.crowdBody, this.crowdHead, this.crowdArmL, this.crowdArmR]) {
      im.instanceMatrix.setUsage(THREE.DynamicDrawUsage)
      im.frustumCulled = false
      im.castShadow = false
      im.receiveShadow = false
      this.scene.add(im)
    }
    const col = new THREE.Color()
    members.forEach((m, i) => {
      col.setHex(m.palette); this.crowdBody.setColorAt(i, col)
      col.setHex(m.skin); this.crowdHead.setColorAt(i, col); this.crowdArmL.setColorAt(i, col); this.crowdArmR.setColorAt(i, col)
    })
    this.crowdBody.instanceColor.needsUpdate = true
    this.crowdHead.instanceColor.needsUpdate = true
    this.crowdArmL.instanceColor.needsUpdate = true
    this.crowdArmR.instanceColor.needsUpdate = true

    this._dummy = new THREE.Object3D()
    this._q = new THREE.Quaternion()
    this._qy = new THREE.Quaternion()
    this._armQ = new THREE.Quaternion()
    this.crowdEnergy = 0.05
    this.crowdTarget = 0.05
    this._updateCrowd(0)
  }

  cheer(amount) {
    this.crowdTarget = clamp(this.crowdTarget + amount, 0.05, 1.4)
    this._cheerHold = Math.max(this._cheerHold || 0, amount > 0.35 ? 1.8 : 0.8)
  }

  _updateCrowd(dt) {
    const dummy = this._dummy
    const q = this._q, qy = this._qy, armQ = this._armQ
    const t = this.time
    const energy = this.crowdTarget
    const members = this.crowd
    for (let i = 0; i < members.length; i++) {
      const m = members[i]
      const cheer = clamp(energy * (0.35 + 0.65 * Math.abs(Math.sin(t * m.speed * 2.2 + m.phase))), 0, 1.4)
      const jump = Math.max(0, Math.sin(t * (3.2 + m.speed) + m.phase)) ** 3 * cheer * 0.28
      const sway = Math.sin(t * 0.9 + m.phase) * 0.012
      const px = m.x + sway
      const py = m.y + jump
      const pz = m.z
      qy.setFromAxisAngle(new THREE.Vector3(0, 1, 0), m.yaw)

      // body
      dummy.position.set(px, py + 0.35 * m.height, pz)
      dummy.quaternion.copy(qy)
      dummy.scale.set(m.girth, m.height, m.girth)
      dummy.updateMatrix()
      this.crowdBody.setMatrixAt(i, dummy.matrix)

      // head, lean toward the sand
      dummy.position.set(px, py + 0.72 * m.height, pz)
      dummy.quaternion.copy(qy)
      dummy.scale.set(1, 1, 1)
      dummy.updateMatrix()
      this.crowdHead.setMatrixAt(i, dummy.matrix)

      // arms: pivot at shoulder, capsules point down by default, rotate up when cheering
      const raise = clamp(cheer * 1.25, 0, 1)
      const swing = Math.sin(t * 5 + m.phase) * 0.4 * raise
      for (const side of [-1, 1]) {
        const ax = px + Math.cos(m.yaw) * side * 0.2 * m.girth
        const az = pz - Math.sin(m.yaw) * side * 0.2 * m.girth
        const ay = py + 0.55 * m.height
        dummy.position.set(ax, ay, az)
        q.setFromEuler(new THREE.Euler(side * (0.15 + raise * 2.05 + swing), m.yaw, 0, 'YXZ'))
        dummy.quaternion.copy(q)
        dummy.scale.set(1, 1, 1)
        dummy.updateMatrix()
        if (side < 0) this.crowdArmL.setMatrixAt(i, dummy.matrix)
        else this.crowdArmR.setMatrixAt(i, dummy.matrix)
      }
    }
    this.crowdBody.instanceMatrix.needsUpdate = true
    this.crowdHead.instanceMatrix.needsUpdate = true
    this.crowdArmL.instanceMatrix.needsUpdate = true
    this.crowdArmR.instanceMatrix.needsUpdate = true
    this.crowdEnergy = energy
  }

  _addTorch(x, y, z, rotX = 0, rotY = 0, withLight = false) {
    const g = new THREE.Group()
    g.position.set(x, y, z)
    const wood = new THREE.MeshStandardMaterial({ map: this.tex.wood, color: 0x9a7550, roughness: 0.9 })
    const iron = new THREE.MeshStandardMaterial({ color: 0x2c2825, metalness: 0.7, roughness: 0.5 })
    const handle = new THREE.Mesh(new THREE.CylinderGeometry(0.035, 0.045, 0.66, 6), wood)
    handle.rotation.z = 0.16
    handle.castShadow = true
    g.add(handle)
    const ring = new THREE.Mesh(new THREE.TorusGeometry(0.065, 0.012, 4, 8), iron)
    ring.rotation.x = Math.PI / 2
    ring.position.y = 0.2
    g.add(ring)
    const flameMat = new THREE.SpriteMaterial({ map: this.tex.flame, color: 0xffd9a0, transparent: true, blending: THREE.AdditiveBlending, depthWrite: false, opacity: 0.95 })
    const flame = new THREE.Sprite(flameMat)
    flame.position.set(0.06, 0.42, 0)
    flame.scale.set(0.3, 0.62, 1)
    g.add(flame)
    const coreMat = new THREE.SpriteMaterial({ map: this.tex.flame, color: 0xfff1c0, transparent: true, blending: THREE.AdditiveBlending, depthWrite: false, opacity: 0.9 })
    const core = new THREE.Sprite(coreMat)
    core.position.set(0.06, 0.4, 0.03)
    core.scale.set(0.16, 0.36, 1)
    g.add(core)
    let light = null
    if (withLight) {
      light = new THREE.PointLight(0xff7a30, 16, 11, 2)
      light.position.set(0.1, 0.48, 0)
      g.add(light)
    }
    g.rotation.x = rotX
    g.rotation.y = rotY
    this.scene.add(g)
    this.torches.push({ group: g, flame, core, light, phase: rand(0, TAU), baseY: 0.42 })
  }

  _torches() {
    const { halfX, halfZ } = ARENA
    // braziers along side walls
    for (const z of [-11, -4, 3, 10]) {
      this._addTorch(-halfX + 0.55, 2.25, z, 0, Math.PI / 2, true)
      this._addTorch(halfX - 0.55, 2.25, z, 0, -Math.PI / 2, false)
    }
    for (const x of [-9, 9]) {
      this._addTorch(x, 2.25, halfZ - 0.55, 0, Math.PI, true)
      this._addTorch(x, 2.25, -halfZ + 0.55, 0, 0, true)
    }
    // standing braziers at corners
    for (const [x, z] of [[-10.5, 13.8], [10.5, 13.8]]) {
      const g = new THREE.Group()
      g.position.set(x, 0, z)
      const iron = new THREE.MeshStandardMaterial({ color: 0x2a2522, metalness: 0.72, roughness: 0.45 })
      const pole = new THREE.Mesh(new THREE.CylinderGeometry(0.06, 0.09, 1.35, 6), iron)
      pole.position.y = 0.68; pole.castShadow = true
      const bowl = new THREE.Mesh(new THREE.CylinderGeometry(0.34, 0.18, 0.26, 8), iron)
      bowl.position.y = 1.42; bowl.castShadow = true
      g.add(pole, bowl)
      const mat = new THREE.SpriteMaterial({ map: this.tex.flame, transparent: true, blending: THREE.AdditiveBlending, depthWrite: false, opacity: 0.95 })
      const fl = new THREE.Sprite(mat); fl.position.y = 1.78; fl.scale.set(0.8, 1.5, 1); g.add(fl)
      const light = new THREE.PointLight(0xff7b32, 22, 13, 2)
      light.position.y = 1.9; g.add(light)
      this.scene.add(g)
      this.torches.push({ group: g, flame: fl, core: null, light, phase: rand(0, TAU), baseY: 1.78, big: true })
    }
  }

  _banners() {
    const mat = new THREE.MeshStandardMaterial({
      map: this.tex.emblem, transparent: true, side: THREE.DoubleSide, roughness: 1,
      color: 0xc9a15f, alphaTest: 0.02
    })
    const cloth = new THREE.MeshStandardMaterial({ map: this.tex.cloth, side: THREE.DoubleSide, roughness: 1, color: 0x9a6f5c })
    const positions = [
      { x: -12.55, y: 2.2, z: -8, ry: Math.PI / 2 },
      { x: -12.55, y: 2.2, z: 6, ry: Math.PI / 2 },
      { x: 12.55, y: 2.2, z: -8, ry: -Math.PI / 2 },
      { x: 12.55, y: 2.2, z: 6, ry: -Math.PI / 2 },
      { x: -4.6, y: 2.25, z: 16.55, ry: Math.PI },
      { x: 4.6, y: 2.25, z: 16.55, ry: Math.PI }
    ]
    for (const p of positions) {
      const g = new THREE.Group()
      g.position.set(p.x, p.y, p.z)
      g.rotation.y = p.ry
      const pole = new THREE.Mesh(new THREE.CylinderGeometry(0.025, 0.025, 2.7, 5), new THREE.MeshStandardMaterial({ color: 0x2b2119, roughness: 0.9 }))
      pole.position.y = 0.25
      g.add(pole)
      const banner = new THREE.Mesh(new THREE.PlaneGeometry(1.55, 2.25, 6, 8), cloth)
      banner.position.set(0, 0.1, 0.03)
      banner.castShadow = true
      const emblem = new THREE.Mesh(new THREE.PlaneGeometry(1.18, 1.18), mat)
      emblem.position.set(0, 0.28, 0.055)
      g.add(banner, emblem)
      this.scene.add(g)
      this.banners.push({ group: g, banner, emblem, phase: rand(0, TAU) })
    }
  }

  _details() {
    // scattered bones near the walls
    const boneMat = new THREE.MeshStandardMaterial({ color: 0xa69472, roughness: 0.85 })
    const boneGeo = new THREE.CylinderGeometry(0.025, 0.018, rand(0.3, 0.5), 5)
    const count = 70
    const inst = new THREE.InstancedMesh(boneGeo, boneMat, count)
    inst.castShadow = true
    const d = new THREE.Object3D()
    for (let i = 0; i < count; i++) {
      const side = randInt(0, 3)
      let x, z
      if (side === 0) { x = rand(-12, 12); z = rand(-16, -13.6) }
      else if (side === 1) { x = rand(-12, 12); z = rand(13.6, 16) }
      else if (side === 2) { x = rand(-12.4, -10.4); z = rand(-15, 15) }
      else { x = rand(10.4, 12.4); z = rand(-15, 15) }
      d.position.set(x, 0.035, z)
      d.rotation.set(rand(-0.2, 0.2), rand(0, TAU), Math.PI / 2 + rand(-0.2, 0.2))
      d.scale.set(1, 1, rand(0.8, 1.6))
      d.updateMatrix()
      inst.setMatrixAt(i, d.matrix)
    }
    this.scene.add(inst)

    // skulls
    const skullMat = new THREE.MeshStandardMaterial({ color: 0xb3a17c, roughness: 0.8 })
    const jawMat = new THREE.MeshStandardMaterial({ color: 0x9c8a66, roughness: 0.9 })
    for (let i = 0; i < 8; i++) {
      const g = new THREE.Group()
      const side = randInt(0, 3)
      let x, z
      if (side === 0) { x = rand(-11.5, 11.5); z = rand(-15.8, -13.8) }
      else if (side === 1) { x = rand(-11.5, 11.5); z = rand(13.8, 15.8) }
      else if (side === 2) { x = rand(-12, -10.6); z = rand(-14, 14) }
      else { x = rand(10.6, 12); z = rand(-14, 14) }
      const skull = new THREE.Mesh(new THREE.SphereGeometry(0.11, 10, 8), skullMat)
      skull.scale.set(0.9, 1, 1.05); skull.castShadow = true
      const jaw = new THREE.Mesh(new THREE.BoxGeometry(0.11, 0.045, 0.09), jawMat)
      jaw.position.set(0, -0.1, 0.025)
      g.add(skull, jaw)
      g.position.set(x, 0.1, z)
      g.rotation.set(rand(-0.4, 0.2), rand(0, TAU), rand(-0.2, 0.2))
      this.scene.add(g)
    }

    // weapon rack at the front wall
    const rackMat = new THREE.MeshStandardMaterial({ map: this.tex.wood, color: 0x8b6744, roughness: 0.9 })
    const metal = new THREE.MeshStandardMaterial({ color: 0x7f7d78, metalness: 0.8, roughness: 0.4 })
    for (const side of [-1, 1]) {
      const g = new THREE.Group()
      g.position.set(side * 8.7, 0, 15.4)
      g.rotation.y = Math.PI
      for (let i = -1; i <= 1; i++) {
        const post = new THREE.Mesh(new THREE.BoxGeometry(0.09, 1.4, 0.09), rackMat)
        post.position.set(i * 0.55, 0.7, 0); post.castShadow = true; g.add(post)
      }
      const bar = new THREE.Mesh(new THREE.BoxGeometry(1.45, 0.08, 0.08), rackMat)
      bar.position.y = 1.1; g.add(bar)
      for (let i = -1; i <= 1; i++) {
        const blade = new THREE.Mesh(new THREE.BoxGeometry(0.055, 0.75, 0.012), metal)
        blade.position.set(i * 0.5, 1.45, 0.03); blade.rotation.z = rand(-0.08, 0.08); g.add(blade)
        const grip = new THREE.Mesh(new THREE.CylinderGeometry(0.02, 0.02, 0.18, 5), new THREE.MeshStandardMaterial({ color: 0x3a2416 }))
        grip.position.set(i * 0.5, 1.02, 0.03); g.add(grip)
      }
      this.scene.add(g)
    }
  }

  _dust() {
    const n = 700
    const geo = new THREE.BufferGeometry()
    const pos = new Float32Array(n * 3)
    this.dustData = []
    for (let i = 0; i < n; i++) {
      const x = rand(-14, 14), y = rand(0.2, 7.5), z = rand(-18, 18)
      pos[i * 3] = x; pos[i * 3 + 1] = y; pos[i * 3 + 2] = z
      this.dustData.push({ x, y, z, p: rand(0, TAU), s: rand(0.04, 0.16), v: rand(0.03, 0.13) })
    }
    geo.setAttribute('position', new THREE.BufferAttribute(pos, 3))
    const mat = new THREE.PointsMaterial({
      map: this.tex.dust, size: 0.075, transparent: true, opacity: 0.32,
      depthWrite: false, blending: THREE.AdditiveBlending, color: 0xffd7a0, sizeAttenuation: true
    })
    this.dust = new THREE.Points(geo, mat)
    this.dust.frustumCulled = false
    this.scene.add(this.dust)
  }

  update(dt, camera) {
    this.time += dt
    // torch flicker
    for (const t of this.torches) {
      const f = 0.78 + Math.sin(this.time * 8.3 + t.phase) * 0.12 + Math.sin(this.time * 17.7 + t.phase * 2.1) * 0.07 + Math.random() * 0.04
      if (t.light) t.light.intensity = (t.big ? 22 : 15) * f
      t.flame.scale.x = (t.big ? 0.8 : 0.3) * (0.9 + f * 0.18)
      t.flame.scale.y = (t.big ? 1.5 : 0.62) * (0.88 + f * 0.24)
      t.flame.material.opacity = 0.78 + f * 0.2
      t.flame.position.y = t.baseY + Math.sin(this.time * 6 + t.phase) * 0.012
      if (t.core) {
        t.core.scale.y = 0.36 * (0.85 + f * 0.3)
        t.core.material.opacity = 0.7 + f * 0.25
      }
    }
    // banners
    for (const b of this.banners) {
      const w = Math.sin(this.time * 1.6 + b.phase) * 0.045 + Math.sin(this.time * 3.1 + b.phase) * 0.015
      b.banner.rotation.y = w
      b.emblem.rotation.y = w * 0.9
      b.banner.rotation.x = Math.sin(this.time * 1.1 + b.phase) * 0.02
      b.emblem.rotation.x = b.banner.rotation.x
    }
    // crowd energy decay
    this.crowdTarget = lerp(this.crowdTarget, 0.055, 1 - Math.exp(-dt * 0.62))
    this._updateCrowd(dt)
    // dust
    const arr = this.dust.geometry.attributes.position.array
    for (let i = 0; i < this.dustData.length; i++) {
      const d = this.dustData[i]
      d.y += d.v * dt
      d.x += Math.sin(this.time * 0.4 + d.p) * 0.06 * dt
      if (d.y > 8.5) { d.y = 0.1; d.x = rand(-14, 14); d.z = rand(-18, 18) }
      arr[i * 3] = d.x; arr[i * 3 + 1] = d.y; arr[i * 3 + 2] = d.z
    }
    this.dust.geometry.attributes.position.needsUpdate = true
    this.dust.material.opacity = 0.24 + Math.sin(this.time * 0.8) * 0.04
  }
}

