import * as THREE from '../vendor/three.module.js'
import { makeBloodTexture, rand, randInt, choice, clamp, lerp, TAU, bloodColor } from './utils.js'
import { ARENA } from './world.js'

const _v = new THREE.Vector3()
const _v2 = new THREE.Vector3()
const _q = new THREE.Quaternion()
const _zAxis = new THREE.Vector3(0, 0, 1)
const _up = new THREE.Vector3(0, 1, 0)
const _m = new THREE.Matrix4()
const _box = new THREE.Box3()

export class GoreSystem {
  constructor(scene, world, audio) {
    this.scene = scene
    this.world = world
    this.audio = audio
    this.time = 0
    this.locked = false
    this.chunks = []
    this.bleeders = []
    this.effects = []
    this.decalMax = 780
    this.decalCursor = 0
    this.fade = 1
    this.fading = false

    this.bloodTex = makeBloodTexture()
    this._buildDecals()
    this._buildDroplets()
    this._mats = {
      skin: new THREE.MeshStandardMaterial({ color: 0xb98a6a, roughness: 0.72 }),
      skinPale: new THREE.MeshStandardMaterial({ color: 0x9d7258, roughness: 0.8 }),
      bone: new THREE.MeshStandardMaterial({ color: 0xd8cba8, roughness: 0.55 }),
      gut: new THREE.MeshStandardMaterial({ color: 0x8a2230, roughness: 0.28, metalness: 0.02 }),
      gutDark: new THREE.MeshStandardMaterial({ color: 0x5c1520, roughness: 0.3 }),
      brain: new THREE.MeshStandardMaterial({ color: 0xc98a8e, roughness: 0.42 }),
      blood: new THREE.MeshStandardMaterial({ color: 0x5c0609, roughness: 0.35 })
    }
    this._halfSkullGeo = new THREE.SphereGeometry(0.145, 16, 12, 0, Math.PI)
    this._cutGeo = new THREE.CircleGeometry(0.144, 16)
    this._brainGeo = new THREE.IcosahedronGeometry(0.05, 1)
    this._organGeo = new THREE.SphereGeometry(1, 8, 6)
    this._shardGeo = new THREE.IcosahedronGeometry(0.05, 0)
  }

  _buildDecals() {
    const geo = new THREE.PlaneGeometry(1, 1)
    const mat = new THREE.MeshLambertMaterial({
      map: this.bloodTex, transparent: true, depthWrite: false, side: THREE.DoubleSide,
      color: 0xffffff, alphaTest: 0.015, polygonOffset: true, polygonOffsetFactor: -3, polygonOffsetUnits: -3
    })
    const im = new THREE.InstancedMesh(geo, mat, this.decalMax)
    im.instanceMatrix.setUsage(THREE.DynamicDrawUsage)
    im.frustumCulled = false
    im.renderOrder = 3
    im.count = 0
    this.decals = im
    this.scene.add(im)
    const c = new THREE.Color()
    this.decalColors = []
    for (let i = 0; i < this.decalMax; i++) this.decalColors.push(c.clone())
  }

  _buildDroplets() {
    const geo = new THREE.IcosahedronGeometry(0.04, 0)
    const mat = new THREE.MeshBasicMaterial({ color: 0x7d060a })
    const n = 620
    const im = new THREE.InstancedMesh(geo, mat, n)
    im.instanceMatrix.setUsage(THREE.DynamicDrawUsage)
    im.frustumCulled = false
    im.count = n
    im.castShadow = false
    this.droplets = im
    this.scene.add(im)
    this.dropData = []
    const d = new THREE.Object3D()
    for (let i = 0; i < n; i++) {
      this.dropData.push({ active: false, pos: new THREE.Vector3(), vel: new THREE.Vector3(), life: 0, size: 1 })
      d.position.set(0, -100, 0); d.scale.setScalar(0); d.updateMatrix()
      im.setMatrixAt(i, d.matrix)
      im.setColorAt(i, bloodColor())
    }
    im.instanceColor.needsUpdate = true
    this.dropCursor = 0
    this._dropDummy = d
  }

  // ---------------------------------------------------------------- decals
  _addDecal(pos, normal, size, tone = 1) {
    if (this.locked) return
    const idx = this.decalCursor
    this.decalCursor = (this.decalCursor + 1) % this.decalMax
    if (this.decals.count < this.decalMax) this.decals.count = Math.min(this.decalMax, this.decals.count + 1)
    const d = this._dropDummy
    d.position.copy(pos).addScaledVector(normal, 0.012)
    d.quaternion.setFromUnitVectors(_zAxis, normal)
    d.quaternion.multiply(_q.setFromAxisAngle(_zAxis, rand(0, TAU)))
    d.scale.set(size * rand(0.8, 1.25), size * rand(0.75, 1.2), 1)
    d.updateMatrix()
    this.decals.setMatrixAt(idx, d.matrix)
    const c = this.decalColors[idx]
    c.setRGB(rand(0.72, 1) * tone, rand(0.55, 0.85) * tone, rand(0.55, 0.85) * tone)
    this.decals.setColorAt(idx, c)
    this.decals.instanceMatrix.needsUpdate = true
    if (this.decals.instanceColor) this.decals.instanceColor.needsUpdate = true
  }

  addGroundDecal(pos, size = 0.7) {
    _v.set(pos.x, 0.012, pos.z)
    this._addDecal(_v, _up, size)
  }

  bloodPool(pos, size = 1) {
    const n = 2 + Math.floor(size * 2)
    for (let i = 0; i < n; i++) {
      this.addGroundDecal({ x: pos.x + rand(-0.3, 0.3) * size, z: pos.z + rand(-0.3, 0.3) * size }, size * rand(0.55, 1.1))
    }
  }

  wallDecal(pos, normal, size = 0.7) {
    _v.copy(pos).addScaledVector(normal, -0.02)
    this._addDecal(_v, normal, size)
  }

  // ---------------------------------------------------------------- droplets
  spawnDroplet(pos, vel, size = 1, life = rand(0.8, 2.2)) {
    if (this.locked) return
    let idx = -1
    for (let k = 0; k < this.dropData.length; k++) {
      const j = (this.dropCursor + k) % this.dropData.length
      if (!this.dropData[j].active) { idx = j; break }
    }
    if (idx < 0) idx = this.dropCursor
    this.dropCursor = (idx + 1) % this.dropData.length
    const p = this.dropData[idx]
    p.active = true
    p.pos.copy(pos)
    p.vel.copy(vel)
    p.life = life
    p.size = size
  }

  bloodBurst(pos, dir, count = 14, power = 1, spread = 0.7) {
    if (this.locked) return
    const n = Math.min(count, 40)
    for (let i = 0; i < n; i++) {
      _v.set(dir.x + rand(-spread, spread), dir.y + rand(-spread * 0.45, spread), dir.z + rand(-spread, spread)).normalize()
      _v.multiplyScalar(rand(1.2, 5.4) * power)
      _v.y += rand(0.4, 2.4)
      this.spawnDroplet(pos, _v, rand(0.6, 1.8))
    }
  }

  addBleeder(object, localPos, duration = 2.2, rate = 24, power = 1) {
    this.bleeders.push({
      object, local: localPos.clone(), time: duration, rate, power, accum: 0
    })
  }

  // ---------------------------------------------------------------- chunks
  addChunk(object, vel, angVel, opts = {}) {
    this.scene.attach(object)
    this.chunks.push({
      object, vel: vel.clone(), angVel: angVel.clone(),
      rest: false, age: 0, gore: !!opts.gore, ttl: opts.ttl || 60
    })
    if (this.chunks.length > 150) {
      const old = this.chunks.shift()
      this.scene.remove(old.object)
    }
    return object
  }

  spawnGuts(pos, dir, count = 6) {
    for (let i = 0; i < count; i++) {
      const mat = Math.random() < 0.5 ? this._mats.gut : this._mats.gutDark
      const m = new THREE.Mesh(this._organGeo, mat)
      const sz = rand(0.035, 0.085)
      m.scale.set(sz * rand(0.7, 1.5), sz * rand(0.9, 2.2), sz)
      m.castShadow = true
      m.position.copy(pos).add(_v.set(rand(-0.1, 0.1), rand(-0.1, 0.1), rand(-0.1, 0.1)))
      this.scene.add(m)
      _v.set(dir.x * rand(0.4, 1.4) + rand(-0.9, 0.9), rand(1, 3.2), dir.z * rand(0.4, 1.4) + rand(-0.9, 0.9))
      this.addChunk(m, _v, _v2.set(rand(-8, 8), rand(-8, 8), rand(-8, 8)), { gore: true })
      this.spawnDroplet(pos, _v.set(rand(-1, 1), rand(0.5, 2), rand(-1, 1)), 1)
    }
    this.bloodBurst(pos, dir, 20, 1.5, 1)
    this.bloodPool(pos, 1.1)
  }

  spawnSkullHalves(pos, skinColor = 0xb98a6a) {
    const skinMat = new THREE.MeshStandardMaterial({ color: skinColor, roughness: 0.7, side: THREE.DoubleSide })
    const cutMat = new THREE.MeshStandardMaterial({ color: 0x6d1016, roughness: 0.45 })
    for (let i = 0; i < 2; i++) {
      const g = new THREE.Group()
      const half = new THREE.Mesh(this._halfSkullGeo, skinMat)
      // scale head shape
      half.scale.set(0.98, 1.12, 0.95)
      half.castShadow = true
      const cut = new THREE.Mesh(this._cutGeo, cutMat)
      cut.scale.set(0.98, 1.12, 1)
      g.add(half, cut)
      if (i === 1) g.rotation.y = Math.PI
      g.position.copy(pos)
      g.position.x += i === 0 ? -0.05 : 0.05
      this.scene.add(g)
      const dir = i === 0 ? -1 : 1
      _v.set(dir * rand(0.9, 2.1), rand(1, 2.4), rand(-1, 1.4))
      this.addChunk(g, _v, _v2.set(rand(-9, 9), rand(-9, 9), rand(-9, 9)), { gore: true })
    }
    for (let i = 0; i < 4; i++) {
      const brain = new THREE.Mesh(this._brainGeo, this._mats.brain)
      brain.scale.setScalar(rand(0.7, 1.4))
      brain.position.copy(pos).add(_v.set(rand(-0.08, 0.08), rand(-0.08, 0.08), rand(-0.08, 0.08)))
      this.scene.add(brain)
      _v.set(rand(-2, 2), rand(0.8, 2.6), rand(-2, 2))
      this.chunks.push({ object: brain, vel: _v.clone(), angVel: _v2.set(rand(-10, 10), rand(-10, 10), rand(-10, 10)), rest: false, age: 0, gore: true, ttl: 60 })
    }
    this.bloodBurst(pos, _up, 22, 1.6, 1)
  }

  spawnSkullFragments(pos, skinColor = 0xb98a6a) {
    const skinMat = new THREE.MeshStandardMaterial({ color: skinColor, roughness: 0.72 })
    const boneMat = this._mats.bone
    for (let i = 0; i < 8; i++) {
      const m = new THREE.Mesh(this._shardGeo, Math.random() < 0.6 ? skinMat : boneMat)
      m.scale.set(rand(0.5, 1.3), rand(0.4, 1.1), rand(0.4, 1.2))
      m.position.copy(pos).add(_v.set(rand(-0.1, 0.1), rand(-0.05, 0.12), rand(-0.1, 0.1)))
      m.castShadow = true
      this.scene.add(m)
      _v.set(rand(-3.4, 3.4), rand(1.2, 4.2), rand(-3.4, 3.4))
      this.addChunk(m, _v, _v2.set(rand(-14, 14), rand(-14, 14), rand(-14, 14)), { gore: true })
    }
    for (let i = 0; i < 5; i++) {
      const brain = new THREE.Mesh(this._brainGeo, this._mats.brain)
      brain.scale.setScalar(rand(0.6, 1.3))
      brain.position.copy(pos).add(_v.set(rand(-0.1, 0.1), rand(-0.08, 0.08), rand(-0.1, 0.1)))
      this.scene.add(brain)
      _v.set(rand(-2.4, 2.4), rand(1, 3.2), rand(-2.4, 2.4))
      this.chunks.push({ object: brain, vel: _v.clone(), angVel: _v2.set(rand(-10, 10), rand(-10, 10), rand(-10, 10)), rest: false, age: 0, gore: true, ttl: 60 })
    }
    this.bloodBurst(pos, _up, 28, 1.8, 1)
  }

  boneSpike(parent, localPos, dir = _up, len = 0.2) {
    const g = new THREE.Group()
    const shaft = new THREE.Mesh(new THREE.CylinderGeometry(0.012, 0.022, len, 5), this._mats.bone)
    shaft.position.y = len / 2
    const knob = new THREE.Mesh(new THREE.SphereGeometry(0.026, 6, 5), this._mats.bone)
    knob.position.y = len
    const blood = new THREE.Mesh(new THREE.SphereGeometry(0.045, 6, 5), this._mats.blood)
    blood.scale.y = 0.5
    g.add(shaft, knob, blood)
    g.position.copy(localPos)
    g.quaternion.setFromUnitVectors(_up, dir.clone().normalize())
    parent.add(g)
    return g
  }

  // ---------------------------------------------------------------- fx
  shockwave(pos, color = 0xffc07a, size = 3.4, duration = 0.5) {
    const mat = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.8, side: THREE.DoubleSide, blending: THREE.AdditiveBlending, depthWrite: false })
    const m = new THREE.Mesh(new THREE.RingGeometry(0.15, 0.28, 36), mat)
    m.rotation.x = -Math.PI / 2
    m.position.copy(pos); m.position.y = 0.04
    this.scene.add(m)
    this.effects.push({ mesh: m, life: duration, max: duration, kind: 'ring', size })
  }

  dustPuff(pos, count = 8, color = 0xa88d68) {
    const mat = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.3, depthWrite: false, blending: THREE.NormalBlending })
    for (let i = 0; i < count; i++) {
      const m = new THREE.Mesh(new THREE.IcosahedronGeometry(rand(0.05, 0.14), 0), mat.clone())
      m.position.copy(pos).add(_v.set(rand(-0.2, 0.2), rand(0, 0.2), rand(-0.2, 0.2)))
      this.scene.add(m)
      this.effects.push({
        mesh: m, life: rand(0.5, 1.1), max: 1.1, kind: 'dust',
        vel: new THREE.Vector3(rand(-0.8, 0.8), rand(0.3, 1), rand(-0.8, 0.8))
      })
    }
  }

  // ---------------------------------------------------------------- update
  update(dt) {
    this.time += dt
    const drops = this.dropData
    const d = this._dropDummy
    const { playerMinX, playerMaxX, playerMinZ, playerMaxZ } = ARENA
    const wallHalfX = 12.98, wallHalfZ = 16.98

    for (let i = 0; i < drops.length; i++) {
      const p = drops[i]
      if (!p.active) continue
      p.life -= dt
      p.vel.y -= 17 * dt
      p.pos.addScaledVector(p.vel, dt)
      // floor
      if (p.pos.y <= 0.02) {
        p.pos.y = 0.02
        this.addGroundDecal(p.pos, clamp(0.16 + p.size * 0.24, 0.14, 0.62))
        p.active = false
        d.position.set(0, -100, 0); d.scale.setScalar(0); d.updateMatrix()
        this.droplets.setMatrixAt(i, d.matrix)
        continue
      }
      // walls
      let hitWall = false
      if (p.pos.x < -wallHalfX) {
        if (p.pos.y < ARENA.wallH) {
          this.wallDecal(_v.set(-wallHalfX, p.pos.y, p.pos.z), _v2.set(1, 0, 0), clamp(0.22 + p.size * 0.3, 0.2, 0.8))
          hitWall = true
        }
        p.pos.x = -wallHalfX
      } else if (p.pos.x > wallHalfX) {
        if (p.pos.y < ARENA.wallH) {
          this.wallDecal(_v.set(wallHalfX, p.pos.y, p.pos.z), _v2.set(-1, 0, 0), clamp(0.22 + p.size * 0.3, 0.2, 0.8))
          hitWall = true
        }
        p.pos.x = wallHalfX
      }
      if (!hitWall && p.pos.z < -wallHalfZ) {
        const nearGate = ARENA.gates.some(g => Math.abs(p.pos.x - g) < 1.7)
        if (!nearGate && p.pos.y < ARENA.wallH) {
          this.wallDecal(_v.set(p.pos.x, p.pos.y, -wallHalfZ), _v2.set(0, 0, 1), clamp(0.22 + p.size * 0.3, 0.2, 0.8))
          hitWall = true
        }
        p.pos.z = -wallHalfZ
      } else if (!hitWall && p.pos.z > wallHalfZ) {
        if (p.pos.y < ARENA.wallH) {
          this.wallDecal(_v.set(p.pos.x, p.pos.y, wallHalfZ), _v2.set(0, 0, -1), clamp(0.22 + p.size * 0.3, 0.2, 0.8))
          hitWall = true
        }
        p.pos.z = wallHalfZ
      }
      if (hitWall || p.life <= 0) {
        p.active = false
        d.position.set(0, -100, 0); d.scale.setScalar(0); d.updateMatrix()
        this.droplets.setMatrixAt(i, d.matrix)
        continue
      }
      d.position.copy(p.pos)
      const s = p.size * (0.7 + clamp(p.life, 0, 1) * 0.4)
      d.scale.setScalar(s)
      d.rotation.set(p.life * 2.3, p.life * 3.1, p.life * 1.7)
      d.updateMatrix()
      this.droplets.setMatrixAt(i, d.matrix)
    }
    this.droplets.instanceMatrix.needsUpdate = true

    // bleeders
    for (let i = this.bleeders.length - 1; i >= 0; i--) {
      const b = this.bleeders[i]
      b.time -= dt
      if (b.time <= 0) { this.bleeders.splice(i, 1); continue }
      b.accum += dt * b.rate
      while (b.accum >= 1) {
        b.accum -= 1
        b.object.updateWorldMatrix(true, false)
        _v.copy(b.local).applyMatrix4(b.object.matrixWorld)
        _v2.set(rand(-0.5, 0.5), rand(-0.2, 0.6), rand(-0.5, 0.5))
        this.spawnDroplet(_v, _v2, rand(0.5, 1.2), rand(0.3, 0.9))
      }
    }

    // chunks
    for (let i = this.chunks.length - 1; i >= 0; i--) {
      const c = this.chunks[i]
      c.age += dt
      if (c.age > c.ttl) {
        this.scene.remove(c.object)
        this.chunks.splice(i, 1)
        continue
      }
      if (c.rest) continue
      c.vel.y -= 19 * dt
      c.object.position.addScaledVector(c.vel, dt)
      c.object.rotation.x += c.angVel.x * dt
      c.object.rotation.y += c.angVel.y * dt
      c.object.rotation.z += c.angVel.z * dt
      c.object.updateWorldMatrix(true, true)
      // floor
      _box.setFromObject(c.object)
      if (_box.min.y < 0.012) {
        const lift = 0.012 - _box.min.y
        c.object.position.y += lift
        if (c.vel.y < 0) c.vel.y *= -0.22
        c.vel.x *= 0.7; c.vel.z *= 0.7
        c.angVel.multiplyScalar(0.62)
        if (Math.abs(c.vel.y) < 0.45 && c.vel.lengthSq() < 0.5) {
          c.rest = true
          c.vel.set(0, 0, 0)
          c.angVel.set(0, 0, 0)
          c.object.updateWorldMatrix(true, true)
          _box.setFromObject(c.object)
          c.object.position.y += Math.max(0, 0.012 - _box.min.y)
          if (c.gore) {
            this.bloodPool(c.object.position, 0.32)
          }
        }
      }
      // arena bounds
      if (c.object.position.x < playerMinX) { c.object.position.x = playerMinX; c.vel.x = Math.abs(c.vel.x) * 0.4 }
      if (c.object.position.x > playerMaxX) { c.object.position.x = playerMaxX; c.vel.x = -Math.abs(c.vel.x) * 0.4 }
      if (c.object.position.z < playerMinZ) { c.object.position.z = playerMinZ; c.vel.z = Math.abs(c.vel.z) * 0.4 }
      if (c.object.position.z > playerMaxZ) { c.object.position.z = playerMaxZ; c.vel.z = -Math.abs(c.vel.z) * 0.4 }
    }

    // effects
    for (let i = this.effects.length - 1; i >= 0; i--) {
      const e = this.effects[i]
      e.life -= dt
      const t = 1 - e.life / e.max
      if (e.life <= 0) {
        this.scene.remove(e.mesh)
        e.mesh.geometry.dispose?.()
        e.mesh.material.dispose?.()
        this.effects.splice(i, 1)
        continue
      }
      if (e.kind === 'ring') {
        e.mesh.scale.setScalar(1 + t * e.size)
        e.mesh.material.opacity = (1 - t) * 0.8
      } else if (e.kind === 'dust') {
        e.mesh.position.addScaledVector(e.vel, dt)
        e.mesh.material.opacity = (1 - t) * 0.28
        e.mesh.scale.multiplyScalar(1 + dt * 1.4)
      }
    }

    // fade handling
    if (this.fading) {
      this.fade = Math.max(0, this.fade - dt / this._fadeDur)
      this.decals.material.opacity = this.fade
      if (this.fade <= 0) this.reset()
    }
  }

  fadeOut(duration = 1.6) {
    this.locked = true
    this.fading = true
    this._fadeDur = duration
    this.fade = 1
  }

  reset() {
    this.decals.count = 0
    this.decalCursor = 0
    this.decals.material.opacity = 1
    this.fade = 1
    this.fading = false
    this.locked = false
    const d = this._dropDummy
    for (let i = 0; i < this.dropData.length; i++) {
      this.dropData[i].active = false
      d.position.set(0, -100, 0); d.scale.setScalar(0); d.updateMatrix()
      this.droplets.setMatrixAt(i, d.matrix)
    }
    this.droplets.instanceMatrix.needsUpdate = true
    for (const c of this.chunks) this.scene.remove(c.object)
    this.chunks.length = 0
    this.bleeders.length = 0
    for (const e of this.effects) this.scene.remove(e.mesh)
    this.effects.length = 0
  }
}

import * as THREE from '../vendor/three.module.js'
import { clamp, damp, lerp, rand, TAU, roundedBox } from './utils.js'

const _forward = new THREE.Vector3()
const _right = new THREE.Vector3()
const _move = new THREE.Vector3()
const _camDir = new THREE.Vector3()

export class Player {
  constructor(game, scene, camera, canvas) {
    this.game = game
    this.scene = scene
    this.camera = camera
    this.canvas = canvas
    this.position = new THREE.Vector3(0, 0, 10.5)
    this.velocity = new THREE.Vector3()
    this.yaw = 0
    this.pitch = -0.04
    this.roll = 0
    this.health = 100
    this.maxHealth = 100
    this.stamina = 100
    this.maxStamina = 100
    this.weapon = 'sword'
    this.attackHeld = false
    this.attackCooldown = 0
    this.swing = { active: false, t: 0, dur: 0.42, hitAt: 0.22, didHit: false, kind: 0 }
    this.dodgeT = 0
    this.dodgeCooldown = 0
    this.dodgeDir = new THREE.Vector3()
    this.invuln = 0
    this.bobPhase = 0
    this.bobAmt = 0
    this.sprintFov = 0
    this.shakeAmt = 0
    this.shakeTime = 0
    this.shakeDur = 0.001
    this.damageFlash = 0
    this.alive = true
    this.lookEnabled = false
    this.sensitivity = 0.0023
    this.moveInput = { x: 0, z: 0 }
    this.keyMove = { x: 0, z: 0 }
    this.joystick = { x: 0, z: 0 }
    this.sprintHeld = false
    this.joystickSprint = false
    this.dragging = false
    this.lastPointer = { x: 0, y: 0 }
    this.time = 0
    this.stepPhase = 0
    this.hitPulse = 0
    this.bloodiness = 0

    this._buildViewmodel()
    this._bindInput()
  }

  setWeapon(w) {
    this.weapon = w
    this.swordGroup.visible = w === 'sword'
    this.hammerGroup.visible = w === 'hammer'
    this.bloodiness = 0
  }

  reset() {
    this.position.set(0, 0, 10.5)
    this.velocity.set(0, 0, 0)
    this.yaw = 0; this.pitch = -0.04; this.roll = 0
    this.health = this.maxHealth
    this.stamina = this.maxStamina
    this.attackHeld = false
    this.attackCooldown = 0
    this.swing.active = false
    this.dodgeT = 0
    this.dodgeCooldown = 0
    this.invuln = 0
    this.alive = true
    this.shakeAmt = 0
    this.damageFlash = 0
    this.bloodiness = 0
    this._updateCamera(0)
  }

  heal(amount) {
    this.health = clamp(this.health + amount, 0, this.maxHealth)
  }

  applyLook(dx, dy, sens = this.sensitivity) {
    if (!this.alive) return
    this.yaw -= dx * sens
    this.pitch -= dy * sens
    this.pitch = clamp(this.pitch, -1.32, 1.28)
    if (this.yaw > Math.PI) this.yaw -= TAU
    if (this.yaw < -Math.PI) this.yaw += TAU
  }

  shake(amount, duration = 0.28) {
    this.shakeAmt = Math.max(this.shakeAmt, amount)
    this.shakeDur = duration
    this.shakeTime = duration
  }

  damage(amount, sourcePos = null) {
    if (!this.alive || this.invuln > 0) return
    this.health -= amount
    this.invuln = 0.32
    this.damageFlash = 1
    this.shake(0.14, 0.3)
    this.game.audio.hurt(0)
    this.game.ui.damageFlash(amount, sourcePos)
    if (this.health <= 0) {
      this.health = 0
      this.alive = false
      this.game.onPlayerDeath()
    }
  }

  startAttack() {
    if (!this.alive || this.attackCooldown > 0 || this.game.state !== 'playing') return
    const isHammer = this.weapon === 'hammer'
    this.swing.active = true
    this.swing.t = 0
    this.swing.dur = isHammer ? 0.82 : 0.44
    this.swing.hitAt = isHammer ? 0.40 : 0.20
    this.swing.didHit = false
    this.swing.kind = isHammer ? 0 : (this.swing.kind ? 0 : 1)
    this.attackCooldown = isHammer ? 0.9 : 0.46
    this.game.audio.whoosh(0, isHammer)
    if (isHammer) this.shake(0.045, 0.18)
  }

  _bindInput() {
    window.addEventListener('keydown', e => {
      if (e.repeat) return
      const k = e.code
      if (k === 'KeyW' || k === 'ArrowUp') this.keyMove.z += 1
      if (k === 'KeyS' || k === 'ArrowDown') this.keyMove.z -= 1
      if (k === 'KeyA' || k === 'ArrowLeft') this.keyMove.x -= 1
      if (k === 'KeyD' || k === 'ArrowRight') this.keyMove.x += 1
      if (k === 'ShiftLeft' || k === 'ShiftRight') this.sprintHeld = true
      if (k === 'Space') { e.preventDefault(); this.dodge() }
    })
    window.addEventListener('keyup', e => {
      const k = e.code
      if (k === 'KeyW' || k === 'ArrowUp') this.keyMove.z -= 1
      if (k === 'KeyS' || k === 'ArrowDown') this.keyMove.z += 1
      if (k === 'KeyA' || k === 'ArrowLeft') this.keyMove.x += 1
      if (k === 'KeyD' || k === 'ArrowRight') this.keyMove.x -= 1
      if (k === 'ShiftLeft' || k === 'ShiftRight') this.sprintHeld = false
    })
    window.addEventListener('blur', () => {
      this.keyMove.x = 0; this.keyMove.z = 0; this.sprintHeld = false; this.attackHeld = false
    })

    const canvas = this.canvas
    document.addEventListener('mousemove', e => {
      if (!this.alive) return
      if (this.game.state !== 'playing') return
      if (document.pointerLockElement === canvas) {
        this.applyLook(e.movementX, e.movementY)
      } else if (this.dragging) {
        this.applyLook(e.clientX - this.lastPointer.x, e.clientY - this.lastPointer.y)
        this.lastPointer.x = e.clientX; this.lastPointer.y = e.clientY
      }
    })
    canvas.addEventListener('mousedown', e => {
      if (e.button !== 0) return
      if (this.game.state !== 'playing') return
      if (document.pointerLockElement !== canvas) {
        this.dragging = true
        this.lastPointer.x = e.clientX; this.lastPointer.y = e.clientY
        if (this.game.mobile) return
        this.canvas.requestPointerLock?.()
        return
      }
      this.attackHeld = true
      this.startAttack()
    })
    window.addEventListener('mouseup', e => {
      if (e.button === 0) { this.dragging = false; this.attackHeld = false }
    })
    canvas.addEventListener('contextmenu', e => e.preventDefault())
  }

  dodge() {
    if (!this.alive || this.game.state !== 'playing' || this.dodgeCooldown > 0 || this.stamina < 26) return
    this.stamina -= 26
    this.dodgeCooldown = 0.75
    this.dodgeT = 0.2
    this.invuln = Math.max(this.invuln, 0.34)
    this._getMoveDir(_move)
    if (_move.lengthSq() < 0.01) {
      _forward.set(-Math.sin(this.yaw), 0, -Math.cos(this.yaw))
      _move.copy(_forward)
    }
    this.dodgeDir.copy(_move).normalize()
    this.game.audio.whoosh(0, false)
  }

  _getMoveDir(out) {
    const x = clamp(this.keyMove.x + this.joystick.x, -1, 1)
    const z = clamp(this.keyMove.z + this.joystick.z, -1, 1)
    _forward.set(-Math.sin(this.yaw), 0, -Math.cos(this.yaw))
    _right.set(Math.cos(this.yaw), 0, -Math.sin(this.yaw))
    out.set(0, 0, 0).addScaledVector(_right, x).addScaledVector(_forward, z)
    if (out.lengthSq() > 1) out.normalize()
    return out
  }

  update(dt, world) {
    this.time += dt
    this.attackCooldown = Math.max(0, this.attackCooldown - dt)
    this.invuln = Math.max(0, this.invuln - dt)
    this.dodgeCooldown = Math.max(0, this.dodgeCooldown - dt)
    this.damageFlash = Math.max(0, this.damageFlash - dt * 2.2)
    this.hitPulse = Math.max(0, this.hitPulse - dt * 4)

    if (!this.alive) {
      // collapse camera
      this.camera.position.y = damp(this.camera.position.y, 0.45, 5, dt)
      this.camera.rotation.z = damp(this.camera.rotation.z, 1.25, 3, dt)
      return
    }

    const playing = this.game.state === 'playing'
    const move = this._getMoveDir(_move)
    const moving = move.lengthSq() > 0.01
    const wantSprint = (this.sprintHeld || this.joystickSprint) && moving && this.stamina > 4
    const sprint = wantSprint && playing
    const speed = sprint ? 8.2 : 5.1

    if (this.dodgeT > 0) {
      this.dodgeT -= dt
      this.velocity.copy(this.dodgeDir).multiplyScalar(12.5)
      this.velocity.y = 0
    } else if (playing) {
      this.velocity.x = damp(this.velocity.x, move.x * speed, 12, dt)
      this.velocity.z = damp(this.velocity.z, move.z * speed, 12, dt)
    } else {
      this.velocity.x = damp(this.velocity.x, 0, 8, dt)
      this.velocity.z = damp(this.velocity.z, 0, 8, dt)
    }

    this.position.x += this.velocity.x * dt
    this.position.z += this.velocity.z * dt
    const b = this.game.world
    this.position.x = clamp(this.position.x, b.playerMinX, b.playerMaxX)
    this.position.z = clamp(this.position.z, b.playerMinZ, b.playerMaxZ)

    // stamina
    if (sprint) this.stamina = Math.max(0, this.stamina - 20 * dt)
    else this.stamina = Math.min(this.maxStamina, this.stamina + 14 * dt)

    // bob
    const spd = Math.hypot(this.velocity.x, this.velocity.z)
    const bobTarget = spd > 0.3 ? clamp(spd / 8, 0, 1) : 0
    this.bobAmt = damp(this.bobAmt, bobTarget, 8, dt)
    this.bobPhase += dt * (sprint ? 12.5 : 8.2) * clamp(spd / 5, 0.15, 1.5)
    this.stepPhase += dt * spd
    if (this.stepPhase > 2.2 && spd > 1) {
      this.stepPhase = 0
      this.game.audio.splat(rand(-0.25, 0.25), 0.16)
    }

    // attack timeline
    if (this.swing.active) {
      this.swing.t += dt
      if (!this.swing.didHit && this.swing.t >= this.swing.hitAt) {
        this.swing.didHit = true
        this.game.onPlayerSwing(this.weapon, this.swing)
      }
      if (this.swing.t >= this.swing.dur) this.swing.active = false
    }
    if (playing && this.attackHeld) this.startAttack()

    // FOV sprint
    const targetFov = 72 + (sprint ? 7 : 0) + (this.swing.active ? (this.weapon === 'hammer' ? 2.5 : 1.5) : 0)
    this.sprintFov = damp(this.sprintFov, targetFov, 6, dt)
    this.camera.fov = this.sprintFov
    this.camera.updateProjectionMatrix()

    this._updateCamera(dt)
    this._updateViewmodel(dt, spd, sprint)
    this._updateShake(dt)
  }

  _updateCamera(dt) {
    const bobY = Math.sin(this.bobPhase) * 0.035 * this.bobAmt
    const bobX = Math.cos(this.bobPhase * 0.5) * 0.025 * this.bobAmt
    this.camera.position.set(this.position.x + bobX, 1.68 + bobY, this.position.z)
    this.roll = damp(this.roll, -this.velocity.x * 0.0035, 6, dt)
    this.camera.rotation.order = 'YXZ'
    this.camera.rotation.y = this.yaw
    this.camera.rotation.x = this.pitch
    this.camera.rotation.z = this.roll
  }

  _updateShake(dt) {
    if (this.shakeTime > 0) {
      this.shakeTime -= dt
      const k = Math.max(0, this.shakeTime / this.shakeDur)
      const a = this.shakeAmt * k * k
      this.camera.rotation.x += rand(-a, a) * 0.4
      this.camera.rotation.y += rand(-a, a) * 0.4
      this.camera.rotation.z += rand(-a, a) * 0.6
      this.camera.position.y += rand(-a, a) * 0.2
      if (this.shakeTime <= 0) this.shakeAmt = 0
    }
  }

  // ------------------------------------------------------------- viewmodel
  _buildViewmodel() {
    this.vmScene = new THREE.Scene()
    this.vmCamera = new THREE.PerspectiveCamera(55, 1, 0.01, 5)
    this.vmCamera.position.set(0, 0, 0)

    const amb = new THREE.HemisphereLight(0xc8d4e8, 0x2a1710, 0.9)
    this.vmScene.add(amb)
    const key = new THREE.DirectionalLight(0xffd0a0, 2.6)
    key.position.set(-0.6, 1.0, 1.2)
    this.vmScene.add(key)
    const rim = new THREE.DirectionalLight(0xff6a3a, 1.4)
    rim.position.set(0.8, 0.2, -1)
    this.vmScene.add(rim)

    this.weaponRoot = new THREE.Group()
    this.weaponRoot.position.set(0.33, -0.38, -0.55)
    this.vmScene.add(this.weaponRoot)
    this.baseWeaponPos = this.weaponRoot.position.clone()

    const leather = new THREE.MeshStandardMaterial({ color: 0x3a2416, roughness: 0.85 })
    const leatherDark = new THREE.MeshStandardMaterial({ color: 0x24150c, roughness: 0.95 })
    const steel = new THREE.MeshStandardMaterial({ color: 0xbfc7d2, metalness: 0.95, roughness: 0.24 })
    const steelDark = new THREE.MeshStandardMaterial({ color: 0x6e747c, metalness: 0.9, roughness: 0.34 })
    const gold = new THREE.MeshStandardMaterial({ color: 0xc9a15f, metalness: 0.85, roughness: 0.32 })
    const bloodMat = new THREE.MeshStandardMaterial({ color: 0x5e070a, roughness: 0.32 })
    this.bladeMat = steel
    this.bladeBloodMat = bloodMat
    this.goldMat = gold

    // ---- sword
    const sg = new THREE.Group()
    const grip = new THREE.Mesh(new THREE.CylinderGeometry(0.022, 0.026, 0.19, 8), leather)
    grip.position.y = 0.02
    const wrap = new THREE.Mesh(new THREE.CylinderGeometry(0.027, 0.027, 0.13, 8), leatherDark)
    wrap.position.y = 0.02
    const pommel = new THREE.Mesh(new THREE.IcosahedronGeometry(0.042, 1), gold)
    pommel.position.y = -0.095
    const guard = new THREE.Mesh(new THREE.BoxGeometry(0.24, 0.035, 0.055), gold)
    guard.position.y = 0.125
    const guardTipL = new THREE.Mesh(new THREE.ConeGeometry(0.028, 0.07, 4), gold)
    guardTipL.position.set(-0.13, 0.125, 0); guardTipL.rotation.z = Math.PI / 2
    const guardTipR = guardTipL.clone(); guardTipR.position.x = 0.13; guardTipR.rotation.z = -Math.PI / 2
    // blade with tip
    const bladeShape = new THREE.Shape()
    bladeShape.moveTo(-0.028, 0); bladeShape.lineTo(0.028, 0); bladeShape.lineTo(0.028, 0.78)
    bladeShape.lineTo(0, 0.9); bladeShape.lineTo(-0.028, 0.78); bladeShape.closePath()
    const bladeGeo = new THREE.ExtrudeGeometry(bladeShape, { depth: 0.012, bevelEnabled: true, bevelSize: 0.004, bevelThickness: 0.004, bevelSegments: 1, steps: 1 })
    bladeGeo.center()
    const blade = new THREE.Mesh(bladeGeo, steel)
    blade.position.y = 0.59
    blade.rotation.z = Math.PI
    const fuller = new THREE.Mesh(new THREE.BoxGeometry(0.012, 0.68, 0.004), steelDark)
    fuller.position.set(0, 0.55, 0.009)
    const edge = new THREE.Mesh(new THREE.BoxGeometry(0.008, 0.72, 0.014), steelDark)
    edge.position.set(-0.019, 0.55, 0)
    const bloodFilm = new THREE.Mesh(new THREE.BoxGeometry(0.06, 0.72, 0.019), bloodMat)
    bloodFilm.position.y = 0.56
    bloodFilm.scale.set(1, 0.001, 1)
    bloodFilm.visible = false
    this.swordBlood = bloodFilm
    sg.add(grip, wrap, pommel, guard, guardTipL, guardTipR, blade, fuller, edge, bloodFilm)
    sg.position.y = 0.1
    sg.rotation.set(-0.24, 0.08, -0.35)
    this.swordGroup = sg
    this.weaponRoot.add(sg)

    // ---- hammer
    const hg = new THREE.Group()
    const haft = new THREE.Mesh(new THREE.CylinderGeometry(0.026, 0.032, 0.98, 8), leather)
    haft.position.y = 0.2
    const haftWrap = new THREE.Mesh(new THREE.CylinderGeometry(0.034, 0.034, 0.22, 8), leatherDark)
    haftWrap.position.y = -0.08
    const headGeo = roundedBox(0.26, 0.17, 0.16, 0.035, 0.8)
    const head = new THREE.Mesh(headGeo, steelDark)
    head.position.y = 0.73
    const face1 = new THREE.Mesh(new THREE.BoxGeometry(0.03, 0.15, 0.14), steel)
    face1.position.set(0.14, 0.73, 0)
    const face2 = face1.clone(); face2.position.x = -0.14
    const band1 = new THREE.Mesh(new THREE.BoxGeometry(0.035, 0.19, 0.18), gold)
    band1.position.set(0.105, 0.73, 0)
    const band2 = band1.clone(); band2.position.x = -0.105
    const butt = new THREE.Mesh(new THREE.ConeGeometry(0.045, 0.1, 6), gold)
    butt.position.y = -0.33; butt.rotation.x = Math.PI
    const spike = new THREE.Mesh(new THREE.ConeGeometry(0.045, 0.13, 4), steel)
    spike.position.set(0, 0.87, 0)
    const hammerBlood = new THREE.Mesh(new THREE.BoxGeometry(0.28, 0.18, 0.17), bloodMat)
    hammerBlood.position.y = 0.73
    hammerBlood.scale.set(1.02, 0.001, 1.02)
    hammerBlood.visible = false
    this.hammerBlood = hammerBlood
    hg.add(haft, haftWrap, head, face1, face2, band1, band2, butt, spike, hammerBlood)
    hg.position.y = 0.06
    hg.rotation.set(-0.5, -0.12, 0.3)
    this.hammerGroup = hg
    this.hammerGroup.visible = false
    this.weaponRoot.add(hg)

    // slash arc
    const arcGeo = new THREE.RingGeometry(0.42, 0.62, 24, 1, 0.1, Math.PI * 0.86)
    const arcMat = new THREE.MeshBasicMaterial({ color: 0xffe2b0, transparent: true, opacity: 0, side: THREE.DoubleSide, blending: THREE.AdditiveBlending, depthWrite: false })
    this.slashArc = new THREE.Mesh(arcGeo, arcMat)
    this.slashArc.position.set(0.06, -0.02, -0.3)
    this.slashArc.rotation.z = -0.4
    this.slashArc.visible = false
    this.vmScene.add(this.slashArc)
    this.slashMat = arcMat
  }

  _updateViewmodel(dt, spd, sprint) {
    const t = this.time
    const bob = this.bobAmt
    const swayX = Math.sin(t * 1.3) * 0.004 + Math.sin(this.bobPhase * 0.5) * 0.012 * bob
    const swayY = Math.sin(t * 1.7) * 0.004 + Math.cos(this.bobPhase) * 0.016 * bob
    const spr = sprint ? 0.6 : 0
    let px = 0.33 + swayX, py = -0.38 + swayY, pz = -0.55
    let rx = -0.05, ry = 0.03, rz = 0
    let sc = 1

    if (this.weapon === 'sword') {
      rx = -0.24 - spr * 0.2
      ry = 0.1
      rz = -0.36
      pz = -0.5 - spr * 0.04
    } else {
      rx = -0.5 - spr * 0.1
      ry = -0.12
      rz = 0.3
      pz = -0.56 - spr * 0.03
    }

    const s = this.swing
    if (s.active) {
      const k = clamp(s.t / s.dur, 0, 1)
      const isHammer = this.weapon === 'hammer'
      if (isHammer) {
        // windup, slam, recover
        const wind = clamp(k / 0.42, 0, 1)
        const slam = clamp((k - 0.42) / 0.2, 0, 1)
        const rec = clamp((k - 0.62) / 0.38, 0, 1)
        const lift = Math.sin(wind * Math.PI * 0.5)
        const down = Math.sin(slam * Math.PI * 0.5)
        rx = lerp(-0.5, -1.85, lift) + down * 2.2 - rec * 0.5
        py = -0.38 + lift * 0.32 - down * 0.3 + rec * 0.16
        pz = -0.55 + lift * 0.06 - down * 0.22 + rec * 0.1
        px = 0.33 - lift * 0.08 + down * 0.05
        rz = 0.3 - lift * 0.3 + down * 0.2
        if (slam > 0) {
          this.shake(0.02, 0.1)
        }
      } else {
        const sign = s.kind === 0 ? 1 : -1
        const wind = clamp(k / 0.26, 0, 1)
        const cut = clamp((k - 0.26) / 0.22, 0, 1)
        const rec = clamp((k - 0.48) / 0.52, 0, 1)
        const lift = Math.sin(wind * Math.PI * 0.5)
        const slash = Math.sin(cut * Math.PI * 0.5)
        rx = -0.24 - lift * 0.45 + slash * 0.6 - rec * 0.1
        ry = 0.1 + sign * (lift * 0.8 - slash * 1.5 + rec * 0.6)
        rz = -0.36 + sign * (lift * 0.9 - slash * 2.0 + rec * 0.9)
        px = 0.33 + sign * (lift * 0.12 - slash * 0.2 + rec * 0.06)
        py = -0.38 + lift * 0.12 - slash * 0.08
        pz = -0.5 + slash * 0.12
        // slash trail
        this.slashArc.visible = cut > 0 && cut < 1
        this.slashMat.opacity = Math.sin(cut * Math.PI) * 0.45
        this.slashArc.rotation.z = -0.4 + sign * (cut * 2.2 - 1.0)
        this.slashArc.position.x = 0.04 + sign * cut * 0.1
      }
    } else {
      this.slashArc.visible = false
      if (this.weapon === 'hammer') this.slashArc.visible = false
    }

    this.weaponRoot.position.set(px, py, pz)
    this.weaponRoot.rotation.set(rx, ry, rz)
    this.weaponRoot.scale.setScalar(sc)

    // blood build-up on blade
    if (this.bloodiness > 0) {
      const on = this.weapon === 'sword' ? this.swordBlood : this.hammerBlood
      on.visible = true
      on.scale.y = clamp(this.bloodiness, 0.001, 1)
      on.material.color.setRGB(0.36, 0.03, 0.04)
    } else {
      this.swordBlood.visible = false
      this.hammerBlood.visible = false
    }
    this.hammerGroup.visible = this.weapon === 'hammer'
  }

  addBloodOnWeapon(amount = 0.2) {
    this.bloodiness = clamp(this.bloodiness + amount, 0, 1)
  }

  getWorldDirection(out) {
    return this.camera.getWorldDirection(out)
  }

  renderViewModel(renderer) {
    this.vmCamera.aspect = this.camera.aspect
    this.vmCamera.updateProjectionMatrix()
    renderer.clearDepth()
    renderer.render(this.vmScene, this.vmCamera)
  }
}

