import { clamp, rand, randInt } from './utils.js'

const ICONS = {
  sword: `<svg viewBox="0 0 48 48"><path d="M37 3l3 3-5 15-9 9-4-4 9-9 6-14z"/><path d="M19 25l4 4-4 4-2-1-2 5-5 5-3-3 5-5 5-2-1-2 3-5z" opacity=".65"/><path d="M10 32l5 5" stroke="currentColor" stroke-width="3"/></svg>`,
  hammer: `<svg viewBox="0 0 48 48"><path d="M20 18l4-2 13 13-3 3-13-13z" opacity=".7"/><path d="M6 5h15l3 4v7l-3 4H6l-3-4V9l3-4z"/><path d="M10 5v15M18 5v15" stroke="#0a0706" stroke-width="2" opacity=".5"/><path d="M15 19l3 1 5 15-4 1-5-15 1-2z" opacity=".7"/></svg>`
}

export class UI {
  constructor(game) {
    this.game = game
    this.$ = (id) => document.getElementById(id)
    this.cache = {}
    this.bannerTimer = 0
    this.toastTimer = 0
    this.splatCount = 0
    this.mobile = false
    this._bind()
  }

  _bind() {
    for (const card of document.querySelectorAll('.weapon-card')) {
      card.addEventListener('click', () => {
        const w = card.dataset.weapon
        this.game.selectWeapon(w)
        this.game.audio.ui()
      })
    }
    this.$('start-btn').addEventListener('click', () => this.game.startRun())
    this.$('resume-btn').addEventListener('click', () => this.game.resume())
    this.$('quit-btn').addEventListener('click', () => this.game.quitToMenu())
    this.$('restart-btn').addEventListener('click', () => this.game.restart())
    this.$('death-menu-btn').addEventListener('click', () => this.game.quitToMenu())
    this.$('pause-btn').addEventListener('click', () => this.game.togglePause())
    this.$('sound-btn').addEventListener('click', () => this.game.toggleMute())
  }

  setWeapon(w) {
    for (const card of document.querySelectorAll('.weapon-card')) {
      const on = card.dataset.weapon === w
      card.classList.toggle('selected', on)
      card.setAttribute('aria-pressed', String(on))
    }
    this.$('weapon-icon').innerHTML = ICONS[w]
    this.$('weapon-name').textContent = w === 'sword' ? 'ARENA SWORD' : 'WAR HAMMER'
    this.$('weapon-hint').textContent = w === 'sword' ? 'SEVER & CLEAVE' : 'CRUSH & BREAK'
    this.$('crosshair').className = `crosshair ${w}`
  }

  showHUD(on) {
    this.$('hud').classList.toggle('hidden', !on)
  }

  showMenu(on) {
    this.$('menu').classList.toggle('hidden', !on)
  }

  showPause(on) {
    this.$('pause').classList.toggle('hidden', !on)
  }

  showDeath(on) {
    this.$('death').classList.toggle('hidden', !on)
  }

  showMobile(on) {
    this.$('mobile').classList.toggle('hidden', !on)
    this.mobile = on
  }

  setStats({ wave, enemies, kills, score, crowd, health, stamina, cd, weapon }) {
    const c = this.cache
    if (c.wave !== wave) { this.$('wave-num').textContent = wave; c.wave = wave }
    if (c.enemies !== enemies) { this.$('enemies-left').textContent = enemies; c.enemies = enemies }
    if (c.kills !== kills) { this.$('kill-num').textContent = kills; c.kills = kills }
    if (c.score !== score) { this.$('score-num').textContent = score.toLocaleString(); c.score = score }
    if (c.health !== health) {
      this.$('health-fill').style.width = `${clamp(health, 0, 100)}%`
      this.$('health-text').textContent = Math.ceil(health)
      this.$('health-fill').style.background = health < 30
        ? 'linear-gradient(90deg,#450406,#c0171b 70%,#ff4034)'
        : 'linear-gradient(90deg,#52080a,#b31419 70%,#d63c32)'
      c.health = health
    }
    if (c.stamina !== stamina) {
      this.$('stamina-fill').style.width = `${clamp(stamina, 0, 100)}%`
      c.stamina = stamina
    }
    if (c.crowd !== crowd) {
      this.$('crowd-fill').style.width = `${clamp(crowd * 100, 4, 100)}%`
      c.crowd = crowd
    }
    if (c.cd !== cd) {
      this.$('weapon-cd').style.transform = `scaleX(${clamp(1 - cd, 0, 1)})`
      c.cd = cd
    }
    if (c.weapon !== weapon) {
      this.setWeapon(weapon)
      c.weapon = weapon
    }
  }

  banner(title, sub, eyebrow = 'THE GATES OPEN', ms = 2400) {
    const el = this.$('wave-banner')
    this.$('banner-title').textContent = title
    this.$('banner-sub').textContent = sub
    el.querySelector('.banner-eyebrow').textContent = eyebrow
    el.classList.add('show')
    clearTimeout(this.bannerTimer)
    this.bannerTimer = setTimeout(() => el.classList.remove('show'), ms)
  }

  hideBanner() {
    this.$('wave-banner').classList.remove('show')
  }

  toast(text, ms = 1600) {
    const el = this.$('toast')
    el.textContent = text
    el.classList.add('show')
    clearTimeout(this.toastTimer)
    this.toastTimer = setTimeout(() => el.classList.remove('show'), ms)
  }

  killFeed(html, ms = 3800) {
    const feed = this.$('killfeed')
    const item = document.createElement('div')
    item.className = 'kill-item'
    item.innerHTML = html
    feed.prepend(item)
    while (feed.children.length > 6) feed.lastChild.remove()
    setTimeout(() => {
      item.classList.add('out')
      setTimeout(() => item.remove(), 520)
    }, ms)
  }

  hitmarker(strong = false) {
    const el = this.$('hitmarker')
    el.classList.remove('active')
    void el.offsetWidth
    el.classList.add('active')
    el.style.filter = strong ? 'drop-shadow(0 0 4px #c0171b)' : 'none'
  }

  combo(count, label = 'KILL STREAK') {
    const el = this.$('combo')
    el.querySelector('b').textContent = `${count}×`
    el.querySelector('span').textContent = label
    el.classList.add('show')
    clearTimeout(this._comboTimer)
    this._comboTimer = setTimeout(() => el.classList.remove('show'), 1400)
  }

  target(info) {
    const el = this.$('target-tag')
    if (!info) { el.classList.remove('show'); return }
    const p = info.part
    const hp = clamp(p.hp / p.maxHp, 0, 1)
    if (this._targetPart !== p) {
      el.innerHTML = `${p.label}<span class="tt-bar"><i style="width:${hp * 100}%"></i></span>`
      this._targetPart = p
    } else {
      el.querySelector('i').style.width = `${hp * 100}%`
    }
    el.classList.add('show')
  }

  damageFlash(amount, sourcePos) {
    const player = this.game.player
    const v = this.$('blood-screen')
    // red vignette pulse
    let pulse = document.getElementById('dmg-pulse')
    if (!pulse) {
      pulse = document.createElement('div')
      pulse.id = 'dmg-pulse'
      pulse.style.cssText = 'position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse at center,transparent 35%,rgba(150,5,8,.75) 100%);opacity:0;transition:opacity .45s ease-out'
      v.appendChild(pulse)
    }
    pulse.style.transition = 'none'
    pulse.style.opacity = String(clamp(0.35 + amount / 30, 0.35, 1))
    requestAnimationFrame(() => {
      pulse.style.transition = 'opacity .5s ease-out'
      pulse.style.opacity = '0'
    })

    if (Math.random() < 0.7) this.screenSplatter(clamp(0.32 + amount / 45, 0.3, 0.8))

    if (sourcePos) {
      const cam = player.camera
      const dx = sourcePos.x - cam.position.x
      const dz = sourcePos.z - cam.position.z
      const angle = Math.atan2(dx, -dz) - player.yaw
      const deg = (angle * 180 / Math.PI) % 360
      const d = document.createElement('div')
      d.className = 'dmg-dir'
      d.style.setProperty('--r', `${deg}deg`)
      this.$('damage-dirs').appendChild(d)
      setTimeout(() => d.remove(), 950)
    }
  }

  screenSplatter(opacity = 0.6) {
    const wrap = this.$('blood-screen')
    const el = document.createElement('div')
    el.className = 'blood-splat'
    const size = rand(140, 460)
    const top = rand(-8, 78)
    const left = Math.random() < 0.5 ? rand(-10, 26) : rand(58, 96)
    el.style.setProperty('--s', `${size}px`)
    el.style.setProperty('--r', `${rand(-40, 40)}deg`)
    el.style.setProperty('--o', String(opacity))
    el.style.top = `${top}%`
    el.style.left = `${left}%`
    wrap.appendChild(el)
    this.splatCount++
    setTimeout(() => { el.remove(); this.splatCount-- }, 1400)
    if (this.splatCount > 8) {
      const first = wrap.querySelector('.blood-splat')
      first?.remove()
    }
  }

  showDeath(stats) {
    this.$('death-wave').textContent = stats.wave
    this.$('death-kills').textContent = stats.kills
    this.$('death-score').textContent = stats.score.toLocaleString()
    this.$('death-combo').textContent = stats.bestCombo
    this.showDeathScreen()
  }

  showDeathScreen() {
    this.$('death').classList.remove('hidden')
  }

  updatePauseStats(stats) {
    this.$('pause-wave').textContent = stats.wave
    this.$('pause-kills').textContent = stats.kills
    this.$('pause-score').textContent = stats.score.toLocaleString()
  }

  setSoundMuted(muted) {
    this.$('sound-on').classList.toggle('hidden', muted)
    this.$('sound-off').classList.toggle('hidden', !muted)
  }

  // ------------------------------------------------------------- touch
  initTouch() {
    this.mobile = matchMedia('(pointer: coarse)').matches || 'ontouchstart' in window
    this.game.mobile = this.mobile
    if (!this.mobile) return
    document.body.classList.add('touch')

    const zone = this.$('stick-zone')
    const knob = this.$('stick-knob')
    let stickId = null
    let base = null
    const maxR = 46
    const setStick = (x, y) => {
      knob.style.transform = `translate(${x}px,${y}px)`
      const p = this.game.player
      p.joystick.x = clamp(x / maxR, -1, 1)
      p.joystick.z = clamp(-y / maxR, -1, 1)
    }
    const resetStick = () => {
      stickId = null
      knob.style.transform = 'translate(0,0)'
      const p = this.game.player
      p.joystick.x = 0; p.joystick.z = 0
    }
    zone.addEventListener('pointerdown', e => {
      stickId = e.pointerId
      zone.setPointerCapture(e.pointerId)
      base = { x: e.clientX, y: e.clientY }
      setStick(0, 0)
      e.preventDefault()
    })
    zone.addEventListener('pointermove', e => {
      if (e.pointerId !== stickId || !base) return
      let dx = e.clientX - base.x, dy = e.clientY - base.y
      const l = Math.hypot(dx, dy)
      if (l > maxR) { dx = dx / l * maxR; dy = dy / l * maxR }
      setStick(dx, dy)
      e.preventDefault()
    })
    const up = e => { if (e.pointerId === stickId) resetStick() }
    zone.addEventListener('pointerup', up)
    zone.addEventListener('pointercancel', up)
    zone.addEventListener('lostpointercapture', up)

    // look drag on the canvas
    const canvas = this.game.canvas
    let lookId = null
    let lastX = 0, lastY = 0
    canvas.addEventListener('pointerdown', e => {
      if (e.pointerType !== 'touch' && e.pointerType !== 'pen') return
      if (this.game.state !== 'playing') return
      if (lookId !== null) return
      lookId = e.pointerId
      lastX = e.clientX; lastY = e.clientY
      canvas.setPointerCapture?.(e.pointerId)
      e.preventDefault()
    })
    canvas.addEventListener('pointermove', e => {
      if (e.pointerId !== lookId) return
      const dx = e.clientX - lastX, dy = e.clientY - lastY
      lastX = e.clientX; lastY = e.clientY
      this.game.player.applyLook(dx * 1.85, dy * 1.85)
      e.preventDefault()
    })
    const lookUp = e => { if (e.pointerId === lookId) lookId = null }
    canvas.addEventListener('pointerup', lookUp)
    canvas.addEventListener('pointercancel', lookUp)
    canvas.addEventListener('lostpointercapture', lookUp)

    const attack = this.$('btn-attack')
    const sprint = this.$('btn-sprint')
    const dodge = this.$('btn-dodge')
    const press = (btn, down, up) => {
      btn.addEventListener('pointerdown', e => { e.preventDefault(); e.stopPropagation(); down() })
      btn.addEventListener('pointerup', e => { e.preventDefault(); e.stopPropagation(); up?.() })
      btn.addEventListener('pointercancel', e => { e.preventDefault(); up?.() })
      btn.addEventListener('pointerleave', e => { if (e.buttons) up?.() })
    }
    press(attack, () => {
      const p = this.game.player
      p.attackHeld = true
      p.startAttack()
    }, () => { this.game.player.attackHeld = false })
    press(sprint, () => { this.game.player.joystickSprint = true }, () => { this.game.player.joystickSprint = false })
    press(dodge, () => { this.game.player.dodge() })
  }
}

import * as THREE from '../vendor/three.module.js'
import { World } from './world.js'
import { Player } from './player.js'
import { EnemyManager } from './enemy.js'
import { GoreSystem } from './gore.js'
import { AudioEngine } from './audio.js'
import { UI } from './ui.js'
import { clamp, damp, lerp, rand, roman, TAU } from './utils.js'

class Game {
  constructor() {
    this.canvas = document.getElementById('game')
    this.renderer = new THREE.WebGLRenderer({ canvas: this.canvas, antialias: true, powerPreference: 'high-performance' })
    this.renderer.setPixelRatio(Math.min(devicePixelRatio || 1, 2))
    this.renderer.setSize(innerWidth, innerHeight)
    this.renderer.outputColorSpace = THREE.SRGBColorSpace
    this.renderer.toneMapping = THREE.ACESFilmicToneMapping
    this.renderer.toneMappingExposure = 1.08
    this.renderer.shadowMap.enabled = true
    this.renderer.shadowMap.type = THREE.PCFSoftShadowMap

    this.scene = new THREE.Scene()
    this.camera = new THREE.PerspectiveCamera(72, innerWidth / innerHeight, 0.055, 220)
    this.camera.rotation.order = 'YXZ'

    this.state = 'menu'
    this.mobile = matchMedia('(pointer: coarse)').matches || 'ontouchstart' in window
    this.time = 0
    this.wave = 0
    this.kills = 0
    this.score = 0
    this.combo = 0
    this.comboTimer = 0
    this.bestCombo = 0
    this.weapon = 'sword'
    this.timeScale = 1
    this.hitStop = 0
    this.waveQueue = []
    this.spawnTimer = 1
    this.intermissionT = 0
    this.aimTimer = 0
    this.menuAngle = 0.4
    this.stats = { wave: 1, enemies: 0, kills: 0, score: 0, crowd: 0.1, health: 100, stamina: 100, cd: 0, weapon: 'sword' }

    this.audio = new AudioEngine()
    this.world = new World(this.scene, this.renderer)
    Object.assign(this.world, { playerMinX: -12.35, playerMaxX: 12.35, playerMinZ: -16.1, playerMaxZ: 16.25 })
    this.gore = new GoreSystem(this.scene, this.world, this.audio)
    this.player = new Player(this, this.scene, this.camera, this.canvas)
    this.enemies = new EnemyManager(this, this.scene, this.gore)
    this.ui = new UI(this)
    this.ui.initTouch()
    this.ui.setWeapon(this.weapon)
    this.ui.showHUD(false)
    this.ui.showMobile(false)

    this._bind()
    this._cinematicCamera(0)
    this.clock = new THREE.Clock()
    requestAnimationFrame(() => this._loop())
    setTimeout(() => {
      const l = document.getElementById('loading')
      l.classList.add('done')
      setTimeout(() => l.remove(), 800)
    }, 250)
  }

  _bind() {
    addEventListener('resize', () => this._resize())
    document.addEventListener('pointerlockchange', () => {
      if (this.state === 'playing' && !this.mobile && document.pointerLockElement !== this.canvas) {
        this.pause()
      }
    })
    addEventListener('keydown', e => {
      if (e.repeat) return
      if (e.code === 'KeyM') this.toggleMute()
      if (e.code === 'KeyP') {
        if (this.state === 'playing') this.pause()
        else if (this.state === 'paused') this.resume()
      }
      if (e.code === 'Escape') {
        if (this.state === 'playing') this.pause()
      }
    })
    addEventListener('visibilitychange', () => {
      if (document.hidden && this.state === 'playing') this.pause()
    })
    this.canvas.addEventListener('click', () => {
      if (this.state === 'playing' && !this.mobile && document.pointerLockElement !== this.canvas) {
        this._lockPointer()
      }
    })
  }

  _lockPointer() {
    try {
      const p = this.canvas.requestPointerLock?.()
      if (p?.catch) p.catch(() => {})
    } catch {}
  }

  _resize() {
    this.camera.aspect = innerWidth / innerHeight
    this.camera.updateProjectionMatrix()
    this.renderer.setPixelRatio(Math.min(devicePixelRatio || 1, this.mobile ? 1.6 : 2))
    this.renderer.setSize(innerWidth, innerHeight)
  }

  selectWeapon(w) {
    this.weapon = w
    this.player.setWeapon(w)
    this.ui.setWeapon(w)
    this.stats.weapon = w
  }

  startRun() {
    this.audio.init()
    this.audio.resume()
    this.audio.ui()
    if (!this.mobile) this._lockPointer()
    this.ui.showMenu(false)
    this.ui.showDeath(false)
    this.ui.showPause(false)
    this.ui.showHUD(true)
    this.ui.showMobile(this.mobile)
    this.enemies.clearAll()
    this.gore.reset()
    this.player.reset()
    this.player.setWeapon(this.weapon)
    this.kills = 0
    this.score = 0
    this.combo = 0
    this.bestCombo = 0
    this.comboTimer = 0
    this.wave = 0
    this.state = 'playing'
    this.world.crowdTarget = 0.16
    this.startWave(1)
    this.ui.toast(this.weapon === 'sword'
      ? 'LMB TO SWING — CUT LIMBS, HEADS AND GUTS TO FEED THE CROWD'
      : 'LMB TO SWING — BREAK BONE, BURST SKULLS, RIP JAWS', 5200)
  }

  restart() {
    this.ui.showDeath(false)
    this.startRun()
  }

  quitToMenu() {
    this.state = 'menu'
    this.enemies.clearAll()
    this.gore.reset()
    this.player.attackHeld = false
    this.player.alive = true
    this.player.health = this.player.maxHealth
    this.ui.showMenu(true)
    this.ui.showDeath(false)
    this.ui.showPause(false)
    this.ui.showHUD(false)
    this.ui.showMobile(false)
    this.ui.hideBanner()
    this.world.crowdTarget = 0.05
    this.audio.setCrowd(0.05)
    if (document.pointerLockElement) document.exitPointerLock()
  }

  pause() {
    if (this.state !== 'playing') return
    this.state = 'paused'
    this.player.attackHeld = false
    this.ui.updatePauseStats({ wave: roman(this.wave), kills: this.kills, score: this.score })
    this.ui.showPause(true)
    this.ui.showMobile(false)
    if (document.pointerLockElement) document.exitPointerLock()
    this.audio.setCrowd(0.05)
  }

  resume() {
    if (this.state !== 'paused') return
    this.state = 'playing'
    this.ui.showPause(false)
    this.ui.showMobile(this.mobile)
    this.audio.resume()
    if (!this.mobile) this._lockPointer()
  }

  togglePause() {
    if (this.state === 'playing') this.pause()
    else if (this.state === 'paused') this.resume()
  }

  toggleMute() {
    this.muted = !this.muted
    this.audio.setMuted(this.muted)
    this.ui.setSoundMuted(this.muted)
    if (this.audio.ready) this.audio.ui()
  }

  startWave(n) {
    this.wave = n
    this.state = 'playing'
    this.waveQueue = this._waveComposition(n)
    this.spawnTimer = 0.55
    this.enemies.difficulty = n - 1
    this.world.cheer(0.7)
    this.audio.waveStart()
    const count = this.waveQueue.length
    this.ui.banner(`WAVE ${roman(n)}`, `${count} FIGHTER${count === 1 ? '' : 'S'} — SURVIVE`, n === 1 ? 'THE GATES OPEN' : 'THE CROWD DEMANDS MORE', 2600)
    if (n > 1) {
      this.player.heal(18)
      this.ui.toast(`WAVE CLEARED — VITALITY RESTORED`, 2400)
    }
  }

  _waveComposition(n) {
    const count = Math.min(3 + n * 2, 16)
    const q = []
    for (let i = 0; i < count; i++) {
      let type = 'raider'
      if (n >= 2 && i % 4 === 2) type = 'gladiator'
      if (n >= 4 && i % 6 === 5) type = 'brute'
      if (n >= 6 && i % 5 === 3) type = 'gladiator'
      if (n >= 7 && i % 7 === 6) type = 'brute'
      q.push(type)
    }
    return q
  }

  completeWave() {
    if (this.state !== 'playing') return
    this.state = 'intermission'
    this.intermissionT = 5.4
    this.score += 250 * this.wave
    this.world.cheer(1.4)
    this.audio.cheer(1)
    this.player.heal(14)
    this.gore.fadeOut(2.2)
    this.ui.banner('WAVE CLEARED', 'THE SAND IS SWEPT CLEAN — THE GATES WILL OPEN AGAIN', 'THE CROWD ROARS', 3600)
    this.ui.toast(`WAVE BONUS +${(250 * this.wave).toLocaleString()}`, 2800)
  }

  update(dt) {
    this.time += dt
    this.ui.setStats({
      wave: roman(Math.max(1, this.wave)),
      enemies: this.enemies.aliveCount + this.waveQueue.length,
      kills: this.kills,
      score: this.score,
      crowd: clamp(this.world.crowdTarget, 0, 1),
      health: this.player.health,
      stamina: this.player.stamina,
      cd: this.player.attackCooldown / (this.weapon === 'hammer' ? 0.9 : 0.46),
      weapon: this.weapon
    })
    this.audio.setCrowd(this.world.crowdTarget)
    this.audio.update(dt)
    this.world.update(dt, this.camera)
    this.gore.update(dt)

    // combos
    if (this.comboTimer > 0) {
      this.comboTimer -= dt
      if (this.comboTimer <= 0) this.combo = 0
    }

    if (this.state === 'menu') {
      this._cinematicCamera(dt)
      return
    }
    if (this.state === 'paused') return

    if (this.state === 'dead') {
      this.player.update(dt, this.world)
      return
    }

    this.player.update(dt, this.world)

    if (this.state === 'playing' || this.state === 'intermission') {
      this.enemies.update(dt, this.player)
    }

    if (this.state === 'playing') {
      // spawn queue
      if (this.waveQueue.length) {
        this.spawnTimer -= dt
        const maxAlive = Math.min(3 + Math.floor(this.wave / 2), 7)
        if (this.spawnTimer <= 0 && this.enemies.aliveCount < maxAlive) {
          const type = this.waveQueue.shift()
          const e = this.enemies.spawn(type)
          e.health *= 1 + (this.wave - 1) * 0.055
          e.maxHealth = e.health
          this.spawnTimer = rand(0.75, 1.4)
        }
      }
      if (!this.waveQueue.length && this.enemies.aliveCount === 0) {
        this.completeWave()
      }
      // target readout
      this.aimTimer -= dt
      if (this.aimTimer <= 0) {
        this.aimTimer = 0.09
        const dir = this.camera.getWorldDirection(new THREE.Vector3())
        const info = this.enemies.targetInfo(this.camera.position, dir, 3.2)
        this.ui.target(info)
      }
    } else if (this.state === 'intermission') {
      this.ui.target(null)
      this.intermissionT -= dt
      this.player.heal(dt * 2)
      if (this.intermissionT <= 0) {
        this.gore.reset()
        this.enemies.clearAll()
        this.startWave(this.wave + 1)
      }
    }
  }

  _cinematicCamera(dt) {
    this.menuAngle += dt * 0.075
    const a = this.menuAngle
    const r = 11.5
    const x = Math.sin(a) * r
    const z = 2 + Math.cos(a) * r
    this.camera.position.set(x, 4.0 + Math.sin(a * 0.7) * 0.5, z)
    this.camera.lookAt(0, 1.45, -3)
    this.camera.fov = 60
    this.camera.updateProjectionMatrix()
  }

  onPlayerSwing(weapon, swing) {
    if (this.state !== 'playing') return
    const dir = this.camera.getWorldDirection(new THREE.Vector3())
    const origin = this.camera.position.clone()
    const result = this.enemies.attack(weapon, origin, dir)
    let any = false
    if (result.hits.length) {
      any = this.enemies.applyHits(result.hits, weapon, dir, this.player)
      if (any) {
        this.ui.hitmarker(weapon === 'hammer')
        this.player.addBloodOnWeapon(weapon === 'hammer' ? 0.25 : 0.32)
        this.player.shake(weapon === 'hammer' ? 0.16 : 0.045, weapon === 'hammer' ? 0.3 : 0.12)
        this.hitStop = Math.max(this.hitStop, weapon === 'hammer' ? 0.065 : 0.035)
        if (Math.random() < 0.32) this.ui.screenSplatter(rand(0.18, 0.4))
      }
    }
    if (weapon === 'hammer') {
      const p = any && result.point ? result.point.clone() : new THREE.Vector3(origin.x + dir.x * 1.75, 0.03, origin.z + dir.z * 1.75)
      p.y = Math.min(p.y, 0.1)
      this.gore.shockwave(p, 0xffc07a, 3.2, 0.55)
      this.gore.dustPuff(p, 10, 0xa88d68)
      this.player.shake(0.1, 0.32)
      this.audio.flesh(0.6, 0, false)
      if (!any) {
        this.hitStop = Math.max(this.hitStop, 0.05)
        this.ui.toast('THE SAND TAKES THE BLOW', 900)
      }
    }
  }

  onEnemyKilled(enemy, cause) {
    this.kills++
    this.combo++
    this.comboTimer = 3.2
    this.bestCombo = Math.max(this.bestCombo, this.combo)
    const base = 100 + this.wave * 15
    let bonus = 0
    let verb = 'SLAIN'
    if (cause === 'head') { bonus = 90; verb = enemy.lastWeapon === 'hammer' ? 'SKULL BURST' : 'SKULL SPLIT' }
    else if (cause === 'bisect') { bonus = 170; verb = 'CLEAVED IN TWO' }
    else if (cause === 'chest') { bonus = 140; verb = 'CHEST CAVED IN' }
    else if (cause === 'vital') { bonus = 0; verb = 'SLAIN' }
    this.score += base + bonus
    const gore = cause === 'head' || cause === 'bisect' || cause === 'chest'
    this.world.cheer(gore ? 1.15 : 0.78)
    this.audio.cheer(gore ? 1 : 0.75)
    this.ui.killFeed(`YOU <em>${verb}</em> A ${enemy.type.label} <b>+${base + bonus}</b>`)
    if (this.combo >= 2) this.ui.combo(this.combo, this.combo >= 5 ? 'THE CROWD IS FERAL' : 'KILL STREAK')
    if (gore) {
      this.ui.screenSplatter(rand(0.28, 0.5))
      this.player.shake(0.06, 0.25)
    }
    const d = enemy.root.position.distanceTo(this.player.position)
    if (d < 3) this.ui.screenSplatter(rand(0.35, 0.75))
  }

  onDismember(enemy, part) {
    this.score += 45
    this.world.cheer(0.5)
    this.audio.cheer(0.55)
    const label = part.kind === 'head' ? 'HEAD DESTROYED' : part.kind === 'jaw' ? 'JAW TORN OFF' : `${part.label} SEVERED`
    this.ui.toast(label, 1400)
    this.ui.killFeed(`<em>${label}</em> — ${enemy.type.label} <b>+45</b>`, 2400)
    this.player.addBloodOnWeapon(0.12)
  }

  onFracture(enemy, part) {
    this.score += 30
    this.world.cheer(0.35)
    this.ui.toast(`${part.label} SHATTERED — BONE EXPOSED`, 1300)
    this.ui.killFeed(`<em>BONE BROKEN</em> — ${enemy.type.label} <b>+30</b>`, 2200)
    this.player.addBloodOnWeapon(0.1)
  }

  onPlayerDeath() {
    if (this.state === 'dead') return
    this.state = 'dead'
    this.player.attackHeld = false
    this.world.crowdTarget = 0.03
    this.audio.boo()
    this.audio.setCrowd(0.03)
    this.ui.target(null)
    if (document.pointerLockElement) document.exitPointerLock()
    setTimeout(() => {
      if (this.state !== 'dead') return
      this.ui.showDeath({ wave: roman(this.wave), kills: this.kills, score: this.score, bestCombo: this.bestCombo })
      this.ui.showMobile(false)
    }, 1500)
  }

  render() {
    this.renderer.render(this.scene, this.camera)
    if (this.state === 'playing' || this.state === 'paused' || this.state === 'intermission') {
      this.player.renderViewModel(this.renderer)
    }
  }

  _loop() {
    requestAnimationFrame(() => this._loop())
    let dt = Math.min(this.clock.getDelta(), 0.05)
    if (this.hitStop > 0) {
      this.hitStop -= dt
      dt *= 0.12
    }
    if (this.state === 'dead') dt *= 0.45
    this.update(dt)
    this.render()
  }
}

