  background:linear-gradient(160deg,rgba(24,16,13,.88),rgba(9,6,5,.88));
  border:1px solid rgba(201,161,95,.25);min-width:220px;
  clip-path:polygon(0 0,calc(100% - 10px) 0,100% 10px,100% 100%,10px 100%,0 calc(100% - 10px));
}
.weapon-icon{width:40px;height:40px;color:var(--gold);display:grid;place-items:center}
.weapon-icon svg{width:36px;height:36px;fill:currentColor}
.weapon-meta{display:flex;flex-direction:column;line-height:1.1}
#weapon-name{font-family:var(--font-display);font-size:12px;letter-spacing:.08em;color:#e8d9bd}
#weapon-hint{font-size:9px;letter-spacing:.16em;color:#8f8170;margin-top:3px}
.weapon-cd{position:absolute;left:0;bottom:0;height:2px;width:100%;background:rgba(201,161,95,.12)}
.weapon-cd i{display:block;height:100%;width:100%;background:var(--gold);transform-origin:left;transition:transform .05s linear}
.top-buttons{position:absolute;right:max(18px,env(safe-area-inset-right));top:96px;display:flex;flex-direction:column;gap:7px;pointer-events:auto}
.icon-btn{width:34px;height:34px;border:1px solid rgba(201,161,95,.22);background:rgba(8,6,5,.6);color:#b3a288;display:grid;place-items:center;cursor:pointer;padding:0;transition:.2s}
.icon-btn:hover{color:var(--gold-bright);border-color:var(--gold)}
.icon-btn svg{width:16px;height:16px;fill:currentColor}

/* crosshair */
.crosshair{position:absolute;left:50%;top:50%;width:38px;height:38px;transform:translate(-50%,-50%);opacity:.9;transition:opacity .15s,transform .1s}
.crosshair .ch-dot{position:absolute;left:50%;top:50%;width:3px;height:3px;margin:-1.5px;background:rgba(245,230,210,.9);border-radius:50%;box-shadow:0 0 4px #000}
.crosshair .ch-line{position:absolute;background:rgba(240,225,205,.75);box-shadow:0 0 3px rgba(0,0,0,.8)}
.ch-1,.ch-2{width:1px;height:9px;left:50%;margin-left:-.5px}
.ch-1{top:0}.ch-2{bottom:0}
.ch-3,.ch-4{height:1px;width:9px;top:50%;margin-top:-.5px}
.ch-3{left:0}.ch-4{right:0}
.crosshair.hammer{width:46px;height:46px}
.crosshair.hammer .ch-line{background:rgba(230,190,140,.8)}
#target-tag{
  position:absolute;left:50%;top:calc(50% + 32px);transform:translateX(-50%);
  font-size:10px;letter-spacing:.24em;color:#e9d8bd;text-shadow:0 2px 5px #000;
  opacity:0;transition:opacity .15s;white-space:nowrap;
}
#target-tag.show{opacity:.92}
#target-tag .tt-bar{display:block;width:70px;height:2px;background:rgba(0,0,0,.6);margin:4px auto 0;border:1px solid rgba(201,161,95,.25)}
#target-tag .tt-bar i{display:block;height:100%;background:#b31419;transition:width .1s}
.hitmarker{position:absolute;left:50%;top:50%;width:30px;height:30px;transform:translate(-50%,-50%);opacity:0}
.hitmarker.active{animation:hit .17s ease-out}
.hitmarker i{position:absolute;width:8px;height:1.5px;background:#f5e8d2;box-shadow:0 0 4px #000}
.hitmarker i:nth-child(1){left:0;top:6px;transform:rotate(45deg)}
.hitmarker i:nth-child(2){right:0;top:6px;transform:rotate(-45deg)}
.hitmarker i:nth-child(3){left:0;bottom:6px;transform:rotate(-45deg)}
.hitmarker i:nth-child(4){right:0;bottom:6px;transform:rotate(45deg)}
@keyframes hit{0%{opacity:1;transform:translate(-50%,-50%) scale(.7)}100%{opacity:0;transform:translate(-50%,-50%) scale(1.35)}}
#damage-dirs{position:absolute;inset:0;overflow:hidden}
.dmg-dir{position:absolute;left:50%;top:50%;width:180px;height:180px;margin:-90px;border-radius:50%;border-top:4px solid rgba(200,20,24,.8);filter:blur(1px);animation:dmgFade .9s ease-out forwards}
@keyframes dmgFade{0%{opacity:1;transform:rotate(var(--r)) scale(.9)}100%{opacity:0;transform:rotate(var(--r)) scale(1.15)}}

/* killfeed + combo */
#killfeed{position:absolute;right:max(18px,env(safe-area-inset-right));top:150px;display:flex;flex-direction:column;align-items:flex-end;gap:4px;max-width:280px}
.kill-item{
  font-size:12px;letter-spacing:.08em;color:#d9c7a9;background:linear-gradient(90deg,transparent,rgba(12,8,7,.72));
  padding:4px 10px;border-right:2px solid var(--blood-bright);animation:feedIn .25s ease both;
}
.kill-item b{color:var(--gold-bright);font-weight:600}
.kill-item em{color:#d4483c;font-style:normal}
@keyframes feedIn{from{opacity:0;transform:translateX(14px)}to{opacity:1;transform:none}}
.kill-item.out{animation:feedOut .5s ease forwards}
@keyframes feedOut{to{opacity:0;transform:translateX(20px)}}
#combo{position:absolute;left:50%;top:calc(50% + 78px);transform:translateX(-50%) rotate(-3deg);text-align:center;opacity:0;transition:opacity .2s}
#combo.show{opacity:1}
#combo b{display:block;font-family:var(--font-display);font-size:31px;color:var(--gold-bright);text-shadow:0 3px 12px #000,0 0 20px rgba(200,30,20,.4)}
#combo span{font-size:10px;letter-spacing:.32em;color:#d9b98a}

/* wave banner */
.wave-banner{
  position:absolute;left:0;right:0;top:34%;text-align:center;opacity:0;transform:scale(.96);
  transition:opacity .35s,transform .5s;pointer-events:none;
}
.wave-banner.show{opacity:1;transform:scale(1)}
.banner-eyebrow{display:block;font-size:11px;letter-spacing:.5em;color:var(--gold);margin-bottom:6px}
.wave-banner strong{
  display:block;font-family:var(--font-display);font-weight:900;font-size:clamp(50px,8vw,92px);line-height:1;color:#f0e2c7;
  text-shadow:0 4px 0 #2a0b07,0 0 60px rgba(175,20,25,.35);letter-spacing:.08em;
}
.banner-sub{display:block;margin-top:8px;font-size:12px;letter-spacing:.34em;color:#cdb998}
.toast{
  position:absolute;left:50%;bottom:118px;transform:translateX(-50%);text-align:center;
  font-size:12px;letter-spacing:.16em;color:#e9d6b6;background:rgba(10,7,6,.6);
  border:1px solid rgba(201,161,95,.14);padding:6px 16px;opacity:0;transition:opacity .3s;
  max-width:80vw;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;
}
.toast.show{opacity:1}

/* pause / death */
.pause-screen,.death-screen{
  background:radial-gradient(ellipse at 50% 30%,rgba(38,7,8,.55),rgba(5,4,4,.92) 60%),rgba(4,3,3,.72);
  backdrop-filter:blur(7px);-webkit-backdrop-filter:blur(7px);
}
.pause-card,.death-card{
  width:min(520px,92vw);text-align:center;padding:38px 34px 30px;
  background:linear-gradient(160deg,rgba(24,16,13,.96),rgba(8,6,5,.97));
  border:1px solid rgba(201,161,95,.28);
  box-shadow:0 30px 90px rgba(0,0,0,.7),inset 0 0 80px rgba(120,15,17,.08);
  clip-path:polygon(0 0,calc(100% - 18px) 0,100% 18px,100% 100%,18px 100%,0 calc(100% - 18px));
  animation:menuIn .35s ease both;
}
.pause-card h2,.death-card h2{font-family:var(--font-display);font-size:46px;margin:12px 0 18px;letter-spacing:.08em;color:#f0e2c7;text-shadow:0 0 40px rgba(200,25,28,.3)}
.death-card h2{color:#d72a2b;font-size:56px;text-shadow:0 0 48px rgba(200,25,28,.5),0 4px 0 #2a0506}
.death-line{color:#9f9180;font-size:13px;letter-spacing:.08em;margin:-8px 0 20px}
.pause-stats{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin:0 0 24px}
.pause-stats>div{display:flex;flex-direction:column;gap:4px;padding:10px 6px;border-top:1px solid rgba(201,161,95,.2);border-bottom:1px solid rgba(201,161,95,.1)}
.pause-stats span{font-size:9px;letter-spacing:.2em;color:#8c7f6b}
.pause-stats b{font-family:var(--font-display);font-size:20px;color:#e9d6b6}
.pause-card .start-btn,.death-card .start-btn{margin-bottom:10px}
.pause-hint{margin:14px 0 0;font-size:10px;letter-spacing:.16em;color:#675f53}

/* ---------- mobile ---------- */
.mobile-ui{position:absolute;inset:0;z-index:15;pointer-events:none}
.stick-zone{position:absolute;left:max(20px,env(safe-area-inset-left));bottom:max(26px,env(safe-area-inset-bottom));width:132px;height:132px;pointer-events:auto;touch-action:none}
.stick-base{position:absolute;inset:0;border-radius:50%;border:1px solid rgba(201,161,95,.3);background:radial-gradient(circle,rgba(30,20,16,.45),rgba(10,7,6,.18));box-shadow:inset 0 0 20px rgba(0,0,0,.4)}
.stick-knob{position:absolute;left:50%;top:50%;width:52px;height:52px;margin:-26px;border-radius:50%;background:radial-gradient(circle at 38% 32%,rgba(220,190,150,.85),rgba(120,90,60,.75));border:1px solid rgba(240,210,160,.55);box-shadow:0 4px 14px rgba(0,0,0,.6)}
.mobile-actions{position:absolute;right:max(20px,env(safe-area-inset-right));bottom:max(24px,env(safe-area-inset-bottom));display:flex;align-items:flex-end;gap:12px;pointer-events:none}
.mob-btn{
  pointer-events:auto;border-radius:50%;border:1px solid rgba(201,161,95,.4);
  background:radial-gradient(circle at 35% 30%,rgba(48,32,25,.85),rgba(12,8,7,.78));
  color:#e8d4b3;font-family:var(--font-display);font-size:20px;display:grid;place-items:center;
  touch-action:none;padding:0;box-shadow:0 6px 18px rgba(0,0,0,.45);
}
.mob-btn.small{width:52px;height:52px;font-size:22px;margin-bottom:8px}
.mob-btn.attack{width:84px;height:84px;border-color:rgba(190,30,32,.6);background:radial-gradient(circle at 35% 30%,rgba(120,16,18,.9),rgba(45,6,8,.9))}
.mob-btn.attack svg{width:44px;height:44px;fill:#f0d6b6}
.mob-btn:active{filter:brightness(1.3);transform:scale(.96)}

.loading{position:absolute;inset:0;z-index:60;background:#080505;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:18px;color:#8c7f6b;font-size:11px;letter-spacing:.4em;transition:opacity .6s}
.loading.done{opacity:0;pointer-events:none}
.loading-mark{width:54px;height:54px;border:1px solid rgba(201,161,95,.3);border-top-color:var(--gold);border-radius:50%;animation:spin 1s linear infinite}
@keyframes spin{to{transform:rotate(360deg)}}

/* ---------- responsive ---------- */
@media (max-width:820px){
  .weapon-select{grid-template-columns:1fr;max-width:520px}
  .weapon-card{padding:12px 14px}
  .card-icon{flex-basis:62px;height:62px}
  .card-icon svg{width:42px;height:42px}
  .card-copy p{font-size:12.5px;margin-bottom:5px}
  .card-copy ul{display:none}
  .menu-wrap{padding-top:10px}
  h1{font-size:clamp(54px,16vw,96px)}
  .controls-strip{display:none}
  .touch-note{display:block}
  .fine-print{display:none}
  .hud-center{display:none}
  .hud-big{font-size:34px}
  .vitals{width:46vw}
  .weapon-panel{min-width:0;padding:6px 10px 6px 6px}
  #weapon-hint{display:none}
  .weapon-icon{width:30px;height:30px}
  .weapon-icon svg{width:28px;height:28px}
  .top-buttons{top:auto;bottom:calc(max(24px,env(safe-area-inset-bottom)) + 150px);right:max(18px,env(safe-area-inset-right))}
  #killfeed{top:110px}
  .toast{bottom:210px;font-size:10.5px}
  .pause-stats{grid-template-columns:repeat(2,1fr)}
  .death-card h2{font-size:44px}
}
@media (max-height:560px) and (orientation:landscape){
  .menu-wrap{padding:4px 0}
  h1{font-size:62px;margin:6px 0 4px}
  .tagline{margin-bottom:10px;font-size:11px}
  .brand-kicker{font-size:10px}
  .weapon-select{margin-bottom:10px;gap:8px;grid-template-columns:1fr 1fr;max-width:760px}
  .weapon-card{padding:8px 10px;gap:8px}
  .card-icon{flex-basis:44px;height:44px}
  .card-icon svg{width:32px;height:32px}
  .card-copy p{display:none}
  .card-copy ul{display:flex}
  .card-copy strong{font-size:14px}
  .start-btn{padding:12px 44px 10px}
  .start-text{font-size:16px}
  .fine-print,.controls-strip,.touch-note{display:none}
}
@media (pointer:coarse){
  #game{cursor:none}
  .crosshair{opacity:.75}
}

